window.DATA_READER_RUMEN = [{"num": 1, "title_en": "Greetings", "title_zh": "打招呼", "type": "dialogue", "category": "日常高频情境口语", "tip": "在美国日常交流中，问候语往往只是打破沉默的社交黏合剂。回答时面带微笑说一声 'Good, how are you?' 或 'Not bad, you?' 就能瞬间拉近距离。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Good morning, May. How are you?", "zh": "早啊，小梅。你好吗？", "audio": "rumen_l01_01.mp3"}, {"speaker": "B", "en": "Hi, Tom. I'm fine. And you?", "zh": "嗨，汤姆。我很好，你呢？", "audio": "rumen_l01_02.mp3"}, {"speaker": "A", "en": "Not bad. Thanks.", "zh": "还不错，谢了。", "audio": "rumen_l01_03.mp3"}, {"speaker": "B", "en": "Good. See you.", "zh": "很好，再见。", "audio": "rumen_l01_04.mp3"}, {"speaker": "A", "en": "Bye.", "zh": "再见。", "audio": "rumen_l01_05.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Hi, May. How's it going?", "zh": "嗨，小梅。近来如何？", "audio": "rumen_l01_06.mp3"}, {"speaker": "B", "en": "Great. And how are you doing?", "zh": "很好。那你呢？", "audio": "rumen_l01_07.mp3"}, {"speaker": "A", "en": "Not bad.", "zh": "还不错。", "audio": "rumen_l01_08.mp3"}, {"speaker": "B", "en": "OK. See you later.", "zh": "好吧，再见。", "audio": "rumen_l01_09.mp3"}, {"speaker": "A", "en": "Take care.", "zh": "保重。", "audio": "rumen_l01_10.mp3"}, {"speaker": "B", "en": "You too.", "zh": "你也是。", "audio": "rumen_l01_11.mp3"}]}], "reading": null, "vocab": [{"word": "How's it going?", "phonetic": "[haʊz ɪt ˈɡoʊɪŋ]", "pos": "phrase", "meaning": "近况如何？/ 最近怎么样？", "modern_tip": "现代美语出镜率极高的日常问候，比教科书式的 How are you 更随意、亲切，常用于熟人与同事之间。", "example": {"en": "Hey Mike, how's it going? -- Pretty good, thanks!", "zh": "嘿迈克，最近怎么样？-- 挺好的，多谢！"}}, {"word": "Not bad.", "phonetic": "[nɑːt bæd]", "pos": "phrase", "meaning": "还不错 / 挺顺的", "modern_tip": "母语者最地道的日常回复之一。语气平实淡定，比刻意的 'I am fine' 自然十倍。", "example": {"en": "How's the new job? -- Not bad, learning a lot.", "zh": "新工作怎么样？-- 还不错，学到挺多东西。"}}, {"word": "How are you doing?", "phonetic": "[haʊ ər jʊ ˈduːɪŋ]", "pos": "phrase", "meaning": "最近过得好吗？", "modern_tip": "带有真切关心的问候。如果把重音落在 doing 上，通常表示对方真想听听你近期的生活状态。", "example": {"en": "Long time no see! How are you doing? -- Doing great, thanks!", "zh": "好久不见！你最近过得怎样？-- 过得很棒，谢谢！"}}, {"word": "Take care.", "phonetic": "[teɪk ker]", "pos": "phrase", "meaning": "保重 / 慢走 / 多关照自己", "modern_tip": "非常温暖且自带礼貌温度的告别语，无论亲朋好友还是客户同事道别都极其常用。", "example": {"en": "Have a safe flight, and take care! -- You too, bye!", "zh": "祝你飞行平安，多保重！-- 你也是，再见！"}}, {"word": "See you later.", "phonetic": "[siː jʊ ˈleɪtər]", "pos": "phrase", "meaning": "回头见 / 待会儿见", "modern_tip": "口语中最通用的告别方式之一，常简读为 'See ya!' 或 'Later!'。", "example": {"en": "I gotta run now, see you later! -- See you!", "zh": "我得赶紧走了，回头见！-- 回头见！"}}], "grammar": [{"num": "01", "title": "【问候三巨头场景区分】How are you vs. How's it going? vs. How are you doing?", "formulas": ["How's it going? ＝ How is it going?（随意、高频）", "How are you doing? ＝ 更显关切、口语常用"], "desc": ["传统国内教学几乎只教 'How are you? -- I'm fine, thank you.'，导致中国学生在真实交流中显得过于书面刻板。", "在现实生活中，美国人走廊打照面通常只说一声 'How's it going?'，回复只需要 2 秒钟（'Good, you?' 或 'Not bad!'）。", "只有当对方坐下来、目光注视你并重读 doing 时，才适合展开聊聊近况。"], "examples": ["A: How's it going, Tom?  B: Can't complain! You?", "A: How are you doing today?  B: Pretty good, just busy."]}, {"num": "02", "title": "【社交破冰回复公式】母语者最自然的三档应答策略", "formulas": ["状态极佳：Great! / Pretty good! / Never better!", "平稳日常：Not bad. / Doing alright. / Can't complain.", "略感疲惫：A bit tired, but hanging in there."], "desc": ["很多初学者误以为被问候时必须详细汇报事实，其实大多数日常问候只相当于中文的‘打照面问声好’。", "回答的核心在于保持简练、积极，并在句尾顺带抛回一句 'And you?' 或 'How about you?' 展现社交互动礼貌。"], "examples": ["A: How are you?  B: Pretty good! And you?", "A: How's everything?  B: Not bad at all."]}], "connected_speech": ["连读（Linking）：'How's it' 在录音中连读为 /ˈhaʊ-zɪt/，末尾 /z/ 顺滑连入下一个元音。", "弱读（Weak Form）：'And you?' 中的 'And' 弱化为 /ən/，整句听起来就像 'an-you' /ˈən ˈjuː/。", "失去爆破（Incomplete Explosion）：'Good morning' 中的 /d/ 失去爆破，舌尖触上齿龈即刻收音，紧接着发 /m/。"], "substitution": [], "exercises": []}, {"num": 2, "title_en": "Courtesy", "title_zh": "礼貌", "type": "dialogue", "category": "日常高频情境口语", "tip": "在美语社交礼仪中，'Excuse me' 用于引起注意或在冒犯动作之前（打扰前说）；而 'I'm sorry' 用于产生打扰或过失之后（事后道歉）。两者界限分明，切勿混淆。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me. Are you Ann?", "zh": "对不起，请问你是安吗？", "audio": "rumen_l02_01.mp3"}, {"speaker": "B", "en": "No, I'm not.", "zh": "不，我不是。", "audio": "rumen_l02_02.mp3"}, {"speaker": "A", "en": "I'm sorry. Who's Ann?", "zh": "很抱歉。请问安是哪位？", "audio": "rumen_l02_03.mp3"}, {"speaker": "B", "en": "She is.", "zh": "她是。", "audio": "rumen_l02_04.mp3"}, {"speaker": "A", "en": "Thank you.", "zh": "谢谢。", "audio": "rumen_l02_05.mp3"}, {"speaker": "B", "en": "You're welcome.", "zh": "不客气。", "audio": "rumen_l02_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Hi, I'm Tom.", "zh": "嗨，我是汤姆。", "audio": "rumen_l02_07.mp3"}, {"speaker": "B", "en": "I beg your pardon?", "zh": "对不起，请再说一遍好吗？", "audio": "rumen_l02_08.mp3"}, {"speaker": "A", "en": "I'm Tom.", "zh": "我是汤姆。", "audio": "rumen_l02_09.mp3"}, {"speaker": "B", "en": "Oh! Hi, Tom. I'm May.", "zh": "哦！嗨，汤姆。我是小梅。", "audio": "rumen_l02_10.mp3"}, {"speaker": "A", "en": "Nice to meet you, May.", "zh": "很高兴认识你，小梅。", "audio": "rumen_l02_11.mp3"}, {"speaker": "B", "en": "Pleased to meet you.", "zh": "幸会，幸会。", "audio": "rumen_l02_12.mp3"}]}], "reading": null, "vocab": [{"word": "Excuse me.", "phonetic": "[ɪkˈskjuːz miː]", "pos": "phrase", "meaning": "不好意思 / 打扰一下 / 请问", "modern_tip": "日常搭话、问路、请别人让路或提出请求时的黄金开口短语，极具礼貌分寸。", "example": {"en": "Excuse me, is this seat taken? -- No, go ahead.", "zh": "打扰一下，请问这有人坐吗？-- 没有，请坐。"}}, {"word": "I beg your pardon?", "phonetic": "[aɪ beɡ jʊr ˈpɑːrdn]", "pos": "phrase", "meaning": "请再说一遍好吗？/ 不好意思我没听清", "modern_tip": "传统英美正规礼貌用语。在日常熟人交流中也可以更简洁地说 'Pardon?' 或 'Sorry, could you say that again?'。", "example": {"en": "I beg your pardon? I didn't quite catch that. -- No problem, I said Tom.", "zh": "不好意思请再说一遍？我刚才没听清。-- 没关系，我说我是汤姆。"}}, {"word": "You're welcome.", "phonetic": "[jʊr ˈwelkəm]", "pos": "phrase", "meaning": "不客气 / 不用谢", "modern_tip": "最经典标准的回谢语。现代口语中朋友间也常用 'No problem!' 或 'Anytime!'。", "example": {"en": "Thanks for your help! -- You're welcome, anytime!", "zh": "多谢你的帮助！-- 不客气，随时找我！"}}, {"word": "Nice to meet you.", "phonetic": "[naɪs tə miːt jʊ]", "pos": "phrase", "meaning": "很高兴认识你 / 幸会", "modern_tip": "初次相识结交时的必备礼仪，注意只用于【第一次见面】；熟人再次见面要说 'Nice to see you again.'。", "example": {"en": "Hi, I'm Alex. -- Nice to meet you, Alex, I'm Sarah.", "zh": "嗨，我是亚历克斯。-- 很高兴认识你，亚历克斯，我是萨拉。"}}, {"word": "Pleased to meet you.", "phonetic": "[pliːzd tə miːt jʊ]", "pos": "phrase", "meaning": "非常荣幸认识您 / 幸会", "modern_tip": "比 Nice to meet you 略显庄重正式，常用于职场接待、商务会面或对长辈的初次介绍中。", "example": {"en": "This is our director, Mr. Clark. -- Pleased to meet you, Mr. Clark.", "zh": "这位是我们的主管克拉克先生。-- 幸会，克拉克先生。"}}], "grammar": [{"num": "01", "title": "【礼貌边界】Excuse me 与 I'm sorry 的关键分水岭", "formulas": ["Excuse me：事情发生前（打扰别人、问路、插话、借过）", "I'm sorry：事情发生后（造成不便、认错人、踩到别人、表同情）"], "desc": ["很多中国学习者只要觉得不好意思就下意识说 'Sorry'，这在母语者听来会显得你在为某种过错道歉。", "想找人问话或打招呼时，第一句一定要用 'Excuse me'（借光/请问）；当发现自己认错人时，下一句才接 'I'm sorry'（抱歉弄错了）。"], "examples": ["Excuse me, do you know what time it is?", "Oh, I'm sorry! I thought you were someone else."]}, {"num": "02", "title": "【初次结识黄金套路】打招呼、报名字与答客套", "formulas": ["自我介绍：Hi, I'm [名字] / My name is [名字]", "回应致意：Nice to meet you / Pleased to meet you", "二次确认：I beg your pardon? / Say that again?"], "desc": ["西方社交中介绍名字时，通常会伸出右手轻握或点头致意，并直视对方眼睛。", "听到对方名字若发音特殊或没听清，绝不要含混点头，直接坦诚一句 'I beg your pardon?' 或 'Sorry, how do you spell that?' 反而是非常受尊重的礼貌举动。"], "examples": ["A: Hi, I'm Bruce.  B: Nice to meet you, Bruce. I'm David.", "A: Pleased to meet you, sir.  B: The pleasure is mine."]}], "connected_speech": ["音变同化（Yod Coalescence）：'meet you' 中的 /t/ 与 /j/ 发生同化，连读为极其丝滑的 /ˈmiː-tʃuː/。", "介词弱读：'Pleased to meet you' 中的介词 'to' 弱读为轻微的 /tə/，把重心放在 pleased 和 meet 上。", "声调走势：疑问句 'I beg your pardon?' 句尾必须明显升调（↗），表达客气探询对方再说一遍。"], "substitution": [], "exercises": []}, {"num": 3, "title_en": "Name, Age and Nationality", "title_zh": "姓名、年龄和国籍", "type": "dialogue", "category": "日常高频情境口语", "tip": "在跨文化交流中询问他人信息时，'May I have your name, please?' 比硬生生的 'What's your name?' 尊贵得体很多。对于年龄问题，西方成年人（尤其是女性）通常视为隐私，除非官方填表，否则非必要不主动询问。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me. What's your name?", "zh": "对不起。请问你叫什么名字？", "audio": "rumen_l03_01.mp3"}, {"speaker": "B", "en": "I'm May.", "zh": "我叫小梅。", "audio": "rumen_l03_02.mp3"}, {"speaker": "A", "en": "Hi, May. Where are you from?", "zh": "嗨，小梅。你是哪里人呢？", "audio": "rumen_l03_03.mp3"}, {"speaker": "B", "en": "I'm from Hong Kong. What about you?", "zh": "我是香港人。那你呢？", "audio": "rumen_l03_04.mp3"}, {"speaker": "A", "en": "I'm from Japan.", "zh": "我是日本人。", "audio": "rumen_l03_05.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "May I have your name, please?", "zh": "请问尊姓大名？", "audio": "rumen_l03_06.mp3"}, {"speaker": "B", "en": "My name is May.", "zh": "我叫小梅。", "audio": "rumen_l03_07.mp3"}, {"speaker": "A", "en": "How old are you?", "zh": "你几岁了？", "audio": "rumen_l03_08.mp3"}, {"speaker": "B", "en": "I'm twenty-five.", "zh": "我25岁。", "audio": "rumen_l03_09.mp3"}, {"speaker": "A", "en": "Where are you from?", "zh": "你是哪里人？", "audio": "rumen_l03_10.mp3"}, {"speaker": "B", "en": "I'm from Hong Kong.", "zh": "我是香港人。", "audio": "rumen_l03_11.mp3"}]}], "reading": null, "vocab": [{"word": "Where are you from?", "phonetic": "[wer ər jʊ frʌm]", "pos": "phrase", "meaning": "你是哪里人？/ 你来自哪里？", "modern_tip": "社交破冰最高频的提问之一，可用来开启家乡、文化和旅游话题。", "example": {"en": "Where are you from? -- I'm originally from Chicago, but live in Seattle now.", "zh": "你是哪里人？-- 我老家在芝加哥，不过现在住在西雅图。"}}, {"word": "What about you?", "phonetic": "[wɑːt əˈbaʊt jʊ]", "pos": "phrase", "meaning": "那你呢？/ 你怎么样？", "modern_tip": "极佳的话题弹球器！回答完自己的情况后顺势一抛，既显谦逊又让对话持续自然流淌。", "example": {"en": "I love spicy food. What about you? -- Me too, especially hotpot!", "zh": "我很爱吃辣。你呢？-- 我也是，尤其是火锅！"}}, {"word": "May I have...?", "phonetic": "[meɪ aɪ hæv]", "pos": "phrase", "meaning": "我可以请问/获取……吗？", "modern_tip": "在服务业、商务或正式场合提出请求的黄金句型，比 Can I have 更有教养和风度。", "example": {"en": "May I have your phone number, please? -- Sure, it's 555-0199.", "zh": "请问可以留一下您的电话号码吗？-- 当然，是555-0199。"}}, {"word": "How old are you?", "phonetic": "[haʊ oʊld ər jʊ]", "pos": "phrase", "meaning": "你多大年纪？/ 几岁了？", "modern_tip": "常用于长辈询问小孩，或办理签证、登记等官方行政场景，日常成人社交需慎用。", "example": {"en": "How old are you, little guy? -- I'm five years old!", "zh": "小家伙你几岁啦？-- 我五岁啦！"}}], "grammar": [{"num": "01", "title": "【出身与国籍表达法】I come from vs. I am from", "formulas": ["结构一：I'm from + 城市/国家（口语最常用、最直接）", "结构二：I come from + 城市/国家（强调成长源头）", "结构三：I'm + 国籍形容词（如 I'm Chinese / Japanese）"], "desc": ["表达自己来自何方时，'I'm from Hong Kong' 或 'I'm from Beijing' 远比老书里刻板的长句子要地道清爽。", "注意区分国家名与国籍形容词：China（国家）-> Chinese（中国人/中文）；Japan -> Japanese。"], "examples": ["I am from California. I grew up there.", "She is from France, but her English is spotless."]}, {"num": "02", "title": "【数字与年龄的极简回答】省略 years old 的纯正美语习惯", "formulas": ["正式全称：I am twenty-five years old.", "母语口语极简：I'm twenty-five.（极其常用，干净利落）"], "desc": ["在英美口语中，回答年龄绝大多数人只说数字本身（'I'm 25'），绝不会画蛇添足地说成 'I'm 25 years'（这是常见中式错误，缺了 old 就会语法残缺）。", "要么完整说 '25 years old'，要么干脆利落只说数字 '25'。"], "examples": ["A: How old is your brother?  B: He's eighteen.", "I'm thirty, but people often think I'm twenty-five."]}], "connected_speech": ["连读（Linking）：'What about you' 中的 'What about' 连读为 /ˈwɑː-tə-baʊt/，末尾 /t/ 与 /j/ 再度同化连为 /tʃuː/。", "弱读与同化：'How old are you' 中的 are 极度弱读为轻微的 /ər/，语速快时就像 /ˈhaʊ-oʊld-ər-juː/。", "词尾鼻音：'from' 结尾双唇紧闭发纯正的鼻音 /m/，不要拖尾音。"], "substitution": [], "exercises": []}, {"num": 4, "title_en": "Introductions", "title_zh": "介绍", "type": "dialogue", "category": "日常高频情境口语", "tip": "向他人引见第三者时，直接用 'This is + 名字' 是最自然经典的句型。介绍平辈可以直接叫名（First name），介绍给长辈或商务上级时建议加上称谓（如 Mr. Lin），体现分寸感。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hi, Tom! How's it going?", "zh": "嗨，汤姆！近来如何？", "audio": "rumen_l04_01.mp3"}, {"speaker": "B", "en": "Great! Who's your friend?", "zh": "很好！你的朋友怎么称呼？", "audio": "rumen_l04_02.mp3"}, {"speaker": "A", "en": "Oh! I'm sorry. This is Kay.", "zh": "噪！真抱歉。这位是凯。", "audio": "rumen_l04_03.mp3"}, {"speaker": "B", "en": "Pleased to meet you, Kay.", "zh": "幸会，凯。", "audio": "rumen_l04_04.mp3"}, {"speaker": "C", "en": "Nice to meet you.", "zh": "幸会。", "audio": "rumen_l04_05.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Dad. Please meet my girlfriend, May.", "zh": "爸爸，见见我的女朋友小梅。", "audio": "rumen_l04_06.mp3"}, {"speaker": "B", "en": "Glad to meet you, May.", "zh": "很高兴认识你，小梅。", "audio": "rumen_l04_07.mp3"}, {"speaker": "C", "en": "Glad to meet you, too, Mr. Lin.", "zh": "我也很高兴认识您，林先生。", "audio": null}, {"speaker": "B", "en": "And what is your family name, May?", "zh": "小梅，那么你贵姓呀？", "audio": "rumen_l04_08.mp3"}, {"speaker": "C", "en": "It's Chen. But you may call me May.", "zh": "我姓陈。不过您可以叫我小梅。", "audio": null}, {"speaker": "B", "en": "May Chen. It's a nice name.", "zh": "陈小梅，这是个好名字。", "audio": "rumen_l04_09.mp3"}, {"speaker": "C", "en": "Thank you, sir.", "zh": "谢谢您，先生。", "audio": null}]}], "reading": null, "vocab": [{"word": "This is...", "phonetic": "[ðɪs ɪz]", "pos": "phrase", "meaning": "这位是……（引见他人）", "modern_tip": "英语中把一个人介绍给另一个人时的 No.1 黄金开头句，电话中也常用来指代自己（'This is Tom'）。", "example": {"en": "Dad, this is my classmate, Leo. -- Nice to meet you, Leo.", "zh": "老爸，这位是我的同学利奥。-- 很高兴认识你，利奥。"}}, {"word": "family name", "phonetic": "[ˈfæməli neɪm]", "pos": "n.", "meaning": "姓氏（等同于 last name / surname）", "modern_tip": "西方人名是'名在前，姓在后'（First name + Last name），因此 family name 明确指代家族姓氏。", "example": {"en": "My first name is David, and my family name is Miller.", "zh": "我的名是戴维，我的姓氏是米勒。"}}, {"word": "Please meet...", "phonetic": "[pliːz miːt]", "pos": "phrase", "meaning": "请见见 / 请认识一下……", "modern_tip": "比单调的介绍更有仪式感，多用于向家人引见伴侣、向团队引见新伙伴。", "example": {"en": "Everyone, please meet our new product designer, Amy.", "zh": "各位，请认识一下我们的新产品设计师艾米。"}}, {"word": "You may call me...", "phonetic": "[jʊ meɪ kɔːl miː]", "pos": "phrase", "meaning": "你可以直接叫我……", "modern_tip": "非常优雅的破冰表达。在别人以正式姓名称呼你时，主动释放亲和力，邀请对方称呼你的昵称或英文名。", "example": {"en": "Mr. Chen? -- Just call me May, please.", "zh": "陈先生？-- 叫我小梅就好，别客气。"}}], "grammar": [{"num": "01", "title": "【引见介绍的三重境界】从休闲聚会到正式引荐", "formulas": ["休闲随意：This is [名字].（最常用，老少皆宜）", "热情引荐：I'd like you to meet [名字].（非常地道体面）", "郑重引见：Please meet my [关系], [名字]."], "desc": ["在英美文化中，若两人同时在场但互不认识，中间人有义务主动牵线介绍，避免气氛冷场尴尬。", "介绍顺序原则：通常把较年轻者引见给年长者，把下级引见给上级，体现社交敬意。"], "examples": ["Tom, I'd like you to meet my sister, Emily.", "Professor Davis, please meet my project partner, Kevin."]}, {"num": "02", "title": "【中西姓名称谓大揭秘】为什么不能乱叫别人 'Mr. + 名'？", "formulas": ["全称：Mr. / Ms. + 姓氏（如 Mr. Lin, Ms. Chen）", "昵称昵称：直接叫 First name（如 May, Tom）", "禁忌：切勿用 Mr. + 名字（如叫 Mr. Tom 是典型的中式错误）"], "desc": ["西方尊称 Mr. / Mrs. / Ms. 后面只能跟【姓氏】（Last name/Family name），绝不能跟名（First name）。", "一旦对方说 'You may call me May'，就意味着彼此关系拉近，之后直接称呼名字即可，无需继续拘谨称呼 Mr.。"], "examples": ["Good morning, Mr. Lin. (正确：Lin 为姓)", "Call me David. (对方授权后直接叫名)"]}], "connected_speech": ["连读：'This is' 连读为 /ˈðɪ-sɪz/，/s/ 音清脆顺滑渡入 is 的元音。", "失去爆破：'Glad to meet you' 中的 'Glad' 尾音 /d/ 不爆破，舌根停顿后直接发 to 的 /t/。", "同化连音：'meet you' 读作 /ˈmiː-tʃuː/，这是美式口语中最具标志性的流利度特征。"], "substitution": [], "exercises": []}, {"num": 5, "title_en": "Occupations", "title_zh": "职业", "type": "dialogue", "category": "日常高频情境口语", "tip": "在职场社交中，问别人职业时 'What do you do?' 远比硬邦邦的 'What is your job?' 地道得体十倍。表达供职公司用 'work for + 公司名'，表达工作领域用 'in + 行业'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me, Mr. Li. This is Miss Lin.", "zh": "打扰一下，李先生。这位是林小姐。", "audio": "rumen_l05_01.mp3"}, {"speaker": "B", "en": "How do you do, Miss Lin?", "zh": "林小姐，你好！", "audio": "rumen_l05_02.mp3"}, {"speaker": "C", "en": "How do you do?", "zh": "你好！", "audio": "rumen_l05_03.mp3"}, {"speaker": "A", "en": "Miss Lin works for IBM.", "zh": "林小姐在IBM 公司上班。", "audio": "rumen_l05_04.mp3"}, {"speaker": "B", "en": "What a coincidence! I work in a computer company, too.", "zh": "好巧呀！我也是在一家电脑公司上班。", "audio": "rumen_l05_05.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Hi, Tom! I'd like you to meet my friend, Sal.", "zh": "嗨，汤姆。我想请你见见我的朋友莎儿。", "audio": "rumen_l05_06.mp3"}, {"speaker": "B", "en": "Pleased to meet you, Sal.", "zh": "很高兴认识你，莎儿。", "audio": "rumen_l05_07.mp3"}, {"speaker": "C", "en": "Same here.", "zh": "我也一样。", "audio": "rumen_l05_08.mp3"}, {"speaker": "B", "en": "So, what do you do, Sal?", "zh": "那，你从事哪一行的？", "audio": "rumen_l05_09.mp3"}, {"speaker": "C", "en": "I'm a secretary. What about you?", "zh": "我是个秘书。你呢？", "audio": "rumen_l05_10.mp3"}, {"speaker": "B", "en": "I'm a pilot.", "zh": "我是开飞机的。", "audio": "rumen_l05_11.mp3"}]}], "reading": null, "vocab": [{"word": "What do you do?", "phonetic": "[wɑːt dʊ jʊ duː]", "pos": "phrase", "meaning": "你是从事哪一行的？/ 你是做什么工作的？", "modern_tip": "美语中询问他人职业的终极黄金句。老外几乎从不说 'What's your job?'，那会显得查户口般生硬唐突。", "example": {"en": "What do you do, Sarah? -- I'm a software engineer.", "zh": "萨拉，你是从事什么行业的？-- 我是一名软件工程师。"}}, {"word": "work for...", "phonetic": "[wɜːrk fər]", "pos": "phrase", "meaning": "在……公司工作 / 受聘于……", "modern_tip": "介绍自己雇主的标准用法，后接具体企业名称（如 IBM, Google, Apple）。", "example": {"en": "My brother works for Tesla in California.", "zh": "我哥哥在加州的特斯拉公司工作。"}}, {"word": "What a coincidence!", "phonetic": "[wɑːt ə koʊˈɪnsɪdəns]", "pos": "phrase", "meaning": "好巧啊！/ 真是太巧了！", "modern_tip": "社交对话中制造共鸣神句！当发现对方也是同行业、同校或老乡时，脱口而出这一句瞬间破冰。", "example": {"en": "You went to Stanford too? What a coincidence!", "zh": "你也读斯坦福？天哪真太巧了！"}}, {"word": "Same here.", "phonetic": "[seɪm hɪr]", "pos": "phrase", "meaning": "我也是 / 我也一样", "modern_tip": "日常回应对方感受或状态的高频极简短语，代替单调的 'Me too'。", "example": {"en": "I'm so exhausted after that meeting. -- Same here, need some coffee.", "zh": "开完那个会我简直累垮了。-- 我也一样，急需来杯咖啡。"}}], "grammar": [{"num": "01", "title": "【职业询问三大段位】从入门到高情商职场表达", "formulas": ["经典日常：What do you do?（最推荐，自然百搭）", "委婉职场：What line of work are you in?（你做哪一行的？）", "项目当前：What are you working on these days?（最近忙什么业务？）"], "desc": ["千万不要问人 'What is your job?'，因为在西方人看来，job 带有机械雇佣的色彩，直接这样问显得粗粝而不敬。", "回答职业时，若具体职位是单数名词，务必记得加不定冠词 a/an（如 'I am a teacher', 'I am an architect'）。"], "examples": ["What line of work are you in? -- I'm in digital marketing.", "What do you do? -- I'm a UX designer at Microsoft."]}, {"num": "02", "title": "【公司与行业介词大决战】work for vs. work in vs. work at", "formulas": ["work for + 具体雇主公司（如 work for IBM / Apple）", "work in + 行业或地点（如 work in tech / work in finance / work in New York）", "work at + 具体工作场所或部门（如 work at a hospital / work at the airport）"], "desc": ["想要说明自己的公司时，用 'work for' 最具专业雇员质感；", "如果不想透露具体公司名字，只说所在行业，则用 'work in'（如 'I work in finance' 我做金融的）。"], "examples": ["She works for a law firm in downtown.", "He works in the healthcare industry."]}], "connected_speech": ["辅音闪音（Flap T）：'What a coincidence' 中的 'What a' 连读为 /ˈwɑː-ɾə/，/t/ 在两个元音之间软化发轻快的轻齿龈闪音 /ɾ/（类似快速汉语拼音 d）。", "同化连音：'I'd like you to meet' 中的 'like you' 连读为 /ˈlaɪ-kjuː/。", "介词弱读：'works for IBM' 中的 'for' 弱读为 /fər/，重音牢牢锁定在 IBM 三个字母上。"], "substitution": [], "exercises": []}, {"num": 6, "title_en": "Time", "title_zh": "时间", "type": "dialogue", "category": "日常高频情境口语", "tip": "在美语日常表达中，直接报数字是主流（如 2:30 直接说 'two thirty'，2:45 直接说 'two forty-five'）。而在传统英美文学或广播中，常借用 'quarter'（一刻钟/15分）和 'half'（半小时/30分）。两种方式都能听懂即可。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me. What time is it, please?", "zh": "打扰一下，请问你这儿有合乎我尺寸的蓝色洋装吗？", "audio": "rumen_l06_01.mp3"}, {"speaker": "B", "en": "It's two thirty.", "zh": "现在是两点半。", "audio": "rumen_l06_02.mp3"}, {"speaker": "A", "en": "Thanks. What time is the next train?", "zh": "谢谢。请问下一班火车是几点开？", "audio": "rumen_l06_03.mp3"}, {"speaker": "B", "en": "Two forty-five.", "zh": "2点45分。", "audio": "rumen_l06_04.mp3"}, {"speaker": "A", "en": "I see. Is it on time?", "zh": "我明白了。它准时吗？", "audio": "rumen_l06_05.mp3"}, {"speaker": "B", "en": "Yes, it is.", "zh": "是的，它很准时。", "audio": "rumen_l06_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Hi, Tom. What time is it, please?", "zh": "嗨，汤姆。请问现在几点了？", "audio": "rumen_l06_07.mp3"}, {"speaker": "B", "en": "It's a quarter to seven.", "zh": "现在是6点45分。", "audio": "rumen_l06_08.mp3"}, {"speaker": "A", "en": "Oh, no! I'm late.", "zh": "噢，糟了！我迟到了。", "audio": "rumen_l06_09.mp3"}, {"speaker": "B", "en": "It's OK.", "zh": "没关系。", "audio": "rumen_l06_10.mp3"}, {"speaker": "A", "en": "What do you mean?", "zh": "你说这话什么意思？", "audio": "rumen_l06_11.mp3"}, {"speaker": "B", "en": "My watch is fast.", "zh": "我的表快了。", "audio": "rumen_l06_12.mp3"}]}], "reading": null, "vocab": [{"word": "What time is it?", "phonetic": "[wɑːt taɪm ɪz ɪt]", "pos": "phrase", "meaning": "现在几点了？", "modern_tip": "询问时刻的绝对核心句，礼貌问陌生人时前面加 'Excuse me'，句尾加上 'please'。", "example": {"en": "Excuse me, do you have the time? -- Yeah, it's almost five.", "zh": "打扰一下，请问现在几点了？-- 噢，差不过五点了。"}}, {"word": "on time", "phonetic": "[ɑːn taɪm]", "pos": "phrase", "meaning": "准时 / 按时（不早不晚）", "modern_tip": "非常高频的成语搭配，常用于班机、火车或会议准点运行。", "example": {"en": "The flight arrived right on time despite the bad weather.", "zh": "尽管天气恶劣，航班还是非常准时地到达了。"}}, {"word": "a quarter to...", "phonetic": "[ə ˈkwɔːrtər tuː]", "pos": "phrase", "meaning": "差一刻钟到……点（即某点45分）", "modern_tip": "quarter 为 1/4（即15分钟），'a quarter to seven' 就是差15分到7点（6:45）。", "example": {"en": "The meeting starts at a quarter to ten.", "zh": "会议在九点四十五分开始。"}}, {"word": "fast / slow (watch)", "phonetic": "[fæst / sloʊ]", "pos": "adj.", "meaning": "（钟表）走快了 / 走慢了", "modern_tip": "表示表针不准时的习惯用词：'My watch is 5 minutes fast.'（我的表快了5分钟）。", "example": {"en": "Don't panic! Your clock is ten minutes fast.", "zh": "别慌！你的钟快了整整十分钟。"}}], "grammar": [{"num": "01", "title": "【时刻表达两大门派】数字顺读法 vs. 逆读法", "formulas": ["顺读法（现代现代口语首选）：点数 + 分钟（如 2:30 = two thirty, 6:45 = six forty-five）", "逆读法（传统雅致）：分钟 + past / to + 点数（如 6:45 = a quarter to seven）"], "desc": ["数字顺读法极其好用，永远不会出错，是国际机场与现代职场的首选沟通方式；", "注意区分：'past / after' 表示‘过了几分’（如 ten past eight = 8:10）；'to / till' 表示‘差几分到’（如 ten to eight = 7:50）。"], "examples": ["It's three fifteen. = It's a quarter past three.", "The next train leaves at eight twenty."]}, {"num": "02", "title": "【时间疑问两大句式】What time...? 与 When...?", "formulas": ["精确时刻提问：What time is the next train?（问具体几点几分）", "广泛时间提问：When will you arrive?（可以是某天、某月或某个时刻）"], "desc": ["想确认交通工具时刻表或开会发车点时，使用 'What time' 能逼出精确到分钟的数字；", "表示准时用 'on time'，表示‘及时（赶得上某事）’则用 'in time'。"], "examples": ["What time does the store close tonight?", "We got to the station just in time for the last bus."]}], "connected_speech": ["连读失爆：'What time is it' 中的 'What time' 两个 /t/ 发生叠合，只发一次强送气；'is it' 连读为 /ˈɪ-zɪt/。", "闪音现象：'What do you mean' 中的 'What do' 在美式语速下，/t/ 迅速软化为连音 /ˈwɑː-ɾə-juː miːn/。", "清辅音连读：'two forty-five' 重音落在 forty 的首音节，five 结尾发纯正唇齿音 /v/。"], "substitution": [], "exercises": []}, {"num": 7, "title_en": "Day and Date", "title_zh": "日期", "type": "dialogue", "category": "日常高频情境口语", "tip": "在日常英文交流中，区分 'What day is it?'（问星期几）与 'What's the date?'（问几月几号）是无数中国初学者的易错盲点。日期表达读法与写法有别，写法为 June 6，读法必须读出序数词 the sixth。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "What day is it today, Tom?", "zh": "汤姆，今天是星期几？", "audio": "rumen_l07_01.mp3"}, {"speaker": "B", "en": "It's Monday.", "zh": "今天星期一。", "audio": "rumen_l07_02.mp3"}, {"speaker": "A", "en": "And is today June 6?", "zh": "那么今天是不是6月6日？", "audio": "rumen_l07_03.mp3"}, {"speaker": "B", "en": "Yes, it is. Why?", "zh": "是的。为什么问呢？", "audio": "rumen_l07_04.mp3"}, {"speaker": "A", "en": "Because it's my birthday.", "zh": "因为今天是我的生日。", "audio": "rumen_l07_05.mp3"}, {"speaker": "B", "en": "Happy birthday, May.", "zh": "小梅，祝你生日快乐。", "audio": "rumen_l07_06.mp3"}, {"speaker": "A", "en": "Thank you.", "zh": "谢谢。", "audio": "rumen_l07_07.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "What's today's date, Tom?", "zh": "汤姆，今天是几月几号？", "audio": "rumen_l07_08.mp3"}, {"speaker": "B", "en": "It's February 14.", "zh": "2月14号。", "audio": "rumen_l07_09.mp3"}, {"speaker": "A", "en": "What day is it?", "zh": "星期几？", "audio": "rumen_l07_10.mp3"}, {"speaker": "B", "en": "It's Friday. Why?", "zh": "星期五。怎么啦？", "audio": "rumen_l07_11.mp3"}, {"speaker": "A", "en": "Today is Valentine's Day.", "zh": "今天是情人节。", "audio": "rumen_l07_12.mp3"}, {"speaker": "B", "en": "Happy Valentine's Day.", "zh": "情人节快乐。", "audio": "rumen_l07_13.mp3"}]}], "reading": null, "vocab": [{"word": "What day is it?", "phonetic": "[wɑːt deɪ ɪz ɪt]", "pos": "phrase", "meaning": "今天星期几？", "modern_tip": "必须牢记：问【星期几】用 day（回答 Monday / Friday 等），绝不要跟问几月几号搞混！", "example": {"en": "What day is it today? -- It's Wednesday.", "zh": "今天星期几？-- 星期三。"}}, {"word": "What's the date?", "phonetic": "[wɑːts ðə deɪt]", "pos": "phrase", "meaning": "今天是几号？/ 今天是几月几日？", "modern_tip": "问具体【日历日期】时用 date，回答为月份加序数词（如 February 14th）。", "example": {"en": "What's today's date? -- It's October 26th.", "zh": "今天是几月几号？-- 今天是10月26号。"}}, {"word": "Valentine's Day", "phonetic": "[ˈvæləntaɪnz deɪ]", "pos": "n.", "meaning": "情人节（2月14日）", "modern_tip": "西方极重要的浪漫节日。西方朋友之间也常常友善地道一声 'Happy Valentine's Day!'。", "example": {"en": "Are you doing anything special for Valentine's Day?", "zh": "情人节你有什么特别的安排吗？"}}, {"word": "Why?", "phonetic": "[waɪ]", "pos": "adv.", "meaning": "为什么？/ 怎么啦？（探询因由）", "modern_tip": "在日常会话中常带有好奇或探寻的语调，熟人之间非常精炼顺畅。", "example": {"en": "Can you lend me your car? -- Sure, but why?", "zh": "你能借我你的车吗？-- 当然可以，不过你要干嘛？"}}], "grammar": [{"num": "01", "title": "【终极避坑】What day vs. What's the date 快速判别法", "formulas": ["问星期（周几）：What day is it today? -> It's Monday / Sunday.", "问日期（号数）：What's the date today? -> It's June 6th / February 14th."], "desc": ["口诀记忆法：day 单词短，问的是七天一轮回的星期；date 包含完整字母，问的是日历上的几月几号。", "询问某个具体日期是否正确用一般疑问句：'Is today June 6th?'（今天是不是6月6号？）。"], "examples": ["A: What day is your presentation?  B: It's on Thursday.", "A: What's the date tomorrow?  B: It'll be the first of May."]}, {"num": "02", "title": "【日期的纯正读写密码】美式月日年法", "formulas": ["书写：June 6, 2026 或 Feb 14", "朗读必须加 the：读作 June (the) sixth，February (the) fourteenth"], "desc": ["美式英语习惯把月份放最前面（Month + Day + Year），英式英语喜欢把日子放前面（Day + Month + Year）；", "虽然书写时经常省略序数词后缀 -th，但在口头朗读时，母语者习惯读出序数词（1st = first, 2nd = second, 3rd = third, 6th = sixth）。"], "examples": ["His birthday is on July 4th (July the fourth).", "The contract expires on December 31st."]}], "connected_speech": ["弱读与同化：'is today' 连读为 /ˈɪ-ztə-deɪ/，today 中的 'to' 弱化为 /tə/。", "唇齿音与爆破：'February 14' 中的 14 重音在后半截 /ˌfɔːrˈtiːn/，避免与 40（forty）混淆。", "语调变化：'Happy birthday, May' 语调在 May 上微微扬起再自然回落，充满真诚祝福感。"], "substitution": [], "exercises": []}, {"num": 8, "title_en": "The Weather", "title_zh": "天气", "type": "dialogue", "category": "日常高频情境口语", "tip": "在以英语为母语的国家（尤其是英国和美国东海岸），谈论天气是陌生人破冰、出租车闲聊、电梯社交的万能话题。掌握几个生动的天气词块，保你在任何对话中都不会冷场。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hi, May! I am calling from New York.", "zh": "嗨，小梅！我是从纽约打电话来的。", "audio": "rumen_l08_01.mp3"}, {"speaker": "B", "en": "New York! What are you doing there?", "zh": "纽约！你在那里做什么啊？", "audio": "rumen_l08_02.mp3"}, {"speaker": "A", "en": "I'm here on business.", "zh": "我是来出差的。", "audio": "rumen_l08_03.mp3"}, {"speaker": "B", "en": "How's the weather in New York?", "zh": "纽约的天气怎么样？", "audio": "rumen_l08_04.mp3"}, {"speaker": "A", "en": "It's terrible. It's raining right now.", "zh": "糟透了。现在正在下雨呢。", "audio": "rumen_l08_05.mp3"}, {"speaker": "B", "en": "What a shame!", "zh": "真可惜！", "audio": "rumen_l08_06.mp3"}]}], "reading": {"en": ["There are four seasons in my hometown. It's cool in spring. It's sunny in summer. It's chilly in fall. In winter, it is very cold. Sometimes it even snows."], "zh": ["我家乡有四个季节。春天的天气凉爽，夏天阳光普照，秋天寒冷，而冬天则是非常冷，有时甚至还会下雪呢。"], "sentences": [{"en": "There are four seasons in my hometown.", "zh": "我家乡有四个季节。", "audio": "rumen_l08_07.mp3"}, {"en": "It's cool in spring.", "zh": "春天的天气凉爽，夏天阳光普照，秋天寒冷，而冬天则是非常冷，有时甚至还会下雪呢。", "audio": "rumen_l08_08.mp3"}, {"en": "It's sunny in summer.", "zh": "", "audio": "rumen_l08_09.mp3"}, {"en": "It's chilly in fall.", "zh": "", "audio": "rumen_l08_10.mp3"}, {"en": "In winter, it is very cold.", "zh": "", "audio": "rumen_l08_11.mp3"}, {"en": "Sometimes it even snows.", "zh": "", "audio": "rumen_l08_12.mp3"}]}, "vocab": [{"word": "on business", "phonetic": "[ɑːn ˈbɪznəs]", "pos": "phrase", "meaning": "出差 / 因公办事", "modern_tip": "表达公务外出的固定搭配，对应的是度假休闲的 'on vacation / for pleasure'。", "example": {"en": "I'm in Tokyo on business for the next three days.", "zh": "未来三天我在东京出差。"}}, {"word": "How's the weather?", "phonetic": "[haʊz ðə ˈweðər]", "pos": "phrase", "meaning": "天气怎么样？", "modern_tip": "最经典的探讨天气的提问，也可等同于 'What's the weather like?'。", "example": {"en": "How's the weather back home? -- Sunny and warm!", "zh": "老家那边天气怎么样？-- 阳光明媚，挺暖和的！"}}, {"word": "What a shame!", "phonetic": "[wɑːt ə ʃeɪm]", "pos": "phrase", "meaning": "真遗憾！/ 太可惜了！", "modern_tip": "表示同理心与惋惜的高级感叹短语，等同于 'What a pity!' 或 'That's too bad!'。", "example": {"en": "The concert got canceled because of the storm. -- What a shame!", "zh": "因为暴风雨，音乐会取消了。-- 真太可惜了！"}}, {"word": "chilly", "phonetic": "[ˈtʃɪli]", "pos": "adj.", "meaning": "微凉的 / 颇有凉意的 / 寒气逼人的", "modern_tip": "比 cold 程度稍轻，常用来形容秋冬交替、晨间晚风的沁凉感。", "example": {"en": "It's getting chilly outside, you'd better bring a jacket.", "zh": "外面开始变凉了，你最好带件外套。"}}], "grammar": [{"num": "01", "title": "【天气四大代表形容词】温度阶梯与自然现象", "formulas": ["温暖阶梯：hot（炎热）-> sunny / warm（暖和）-> cool（凉爽）-> chilly（微凉）-> freezing / very cold（极冷）", "天气现象：raining（下雨中）/ snowing（下雪中）/ windy（大风）"], "desc": ["表示天气时，主语永远使用虚指代词 'It'（如 It's raining, It's chilly），千万不要说 'The weather is raining'；", "现在进行时描述眼前天气：'It is raining right now.'（现在正在下着雨呢）。"], "examples": ["It's sunny and mild today, perfect for a walk.", "It was freezing cold in Chicago last winter."]}, {"num": "02", "title": "【出差与度假的社交提问】What are you doing there?", "formulas": ["询问目的：What brings you here? / What are you doing here?", "回答因公：I'm here on business.", "回答休闲：I'm just traveling / on vacation."], "desc": ["在异地偶遇朋友时，'What are you doing there/here?' 表达惊喜的询问对方来意；", "在海关入境问询时，官员问 'What is the purpose of your visit?'，回答也是简明扼要的 'Business' 或 'Pleasure'。"], "examples": ["Are you here on business or vacation? -- Business, meeting our local partners.", "I travel to Singapore on business twice a year."]}], "connected_speech": ["闪音技巧：'What a shame' 中的 'What a' 连读为 /ˈwɑː-ɾə/，/t/ 转化为清脆闪音。", "连读顺滑：'calling from' 中的 /ŋ/ 顺畅滑入 /f/，不需要突兀停顿。", "现在分词节奏：'raining right now' 重音落在 rain 和 now 上，呈现出起伏的美式韵律。"], "substitution": [], "exercises": []}, {"num": 9, "title_en": "Telephone Conversation I", "title_zh": "电话会话（一）", "type": "dialogue", "category": "日常高频情境口语", "tip": "在电话英语中，'我'要说 'This is [名字]'，而不能说 'I am [名字]'；'对方'要说 'Who's calling?'，而不能生硬地问 'Who are you?'。这是英语国际通话最关键的礼仪防线。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hello! May I speak to Bob, please?", "zh": "哈啰！请问我可以跟鲍勃说话吗？", "audio": "rumen_l09_01.mp3"}, {"speaker": "B", "en": "He's not in.", "zh": "他不在。", "audio": "rumen_l09_02.mp3"}, {"speaker": "A", "en": "May I leave a message?", "zh": "我可以留个话吗？", "audio": "rumen_l09_03.mp3"}, {"speaker": "B", "en": "Sure. Go ahead.", "zh": "当然。请说吧。", "audio": "rumen_l09_04.mp3"}, {"speaker": "A", "en": "This is Tom. Please ask him to call me back as soon as possible.", "zh": "我是汤姆。请他尽快回电话给我。", "audio": "rumen_l09_05.mp3"}, {"speaker": "B", "en": "OK. Bye.", "zh": "好的。再见。", "audio": "rumen_l09_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "May I speak to Mr. Wang, please?", "zh": "请问我可以跟王先生说话吗？", "audio": "rumen_l09_07.mp3"}, {"speaker": "B", "en": "Who's calling, please?", "zh": "请问是谁呀？", "audio": "rumen_l09_08.mp3"}, {"speaker": "A", "en": "This is Tom Lin.", "zh": "我是林汤姆。", "audio": "rumen_l09_09.mp3"}, {"speaker": "B", "en": "Hold on, please. (A few seconds later.) He's out at the moment.", "zh": "请稍等一下。（几秒钟后） 他现在出去了。", "audio": "rumen_l09_10.mp3"}, {"speaker": "A", "en": "When will he be back?", "zh": "他什么时候会回来呢？", "audio": "rumen_l09_12.mp3"}, {"speaker": "B", "en": "I don't know.", "zh": "我不知道。", "audio": "rumen_l09_13.mp3"}, {"speaker": "A", "en": "OK, I'll call back later. Bye.", "zh": "好吧。我稍后再打来。再见。", "audio": "rumen_l09_14.mp3"}]}], "reading": null, "vocab": [{"word": "May I speak to...?", "phonetic": "[meɪ aɪ spiːk tuː]", "pos": "phrase", "meaning": "请问我可以找……通话吗？", "modern_tip": "致电他人、请求转接某人的绝对标准礼貌开头，比 Can I talk to 庄重大方很多。", "example": {"en": "Hello, may I speak to Dr. Watson, please? -- Speaking!", "zh": "您好，请问我可以找沃森医生通话吗？-- 我就是！"}}, {"word": "leave a message", "phonetic": "[liːv ə ˈmesɪdʒ]", "pos": "phrase", "meaning": "留个口信 / 留言", "modern_tip": "当对方不在时，主动提出留话用 'May I leave a message?'，对方接线员也会主动问 'Would you like to leave a message?'。", "example": {"en": "He's stepped out of the office. Would you like to leave a message?", "zh": "他刚好走出办公室了。您需要留个口信吗？"}}, {"word": "as soon as possible (ASAP)", "phonetic": "[æz suːn æz ˈpɑːsəbl]", "pos": "phrase", "meaning": "尽快 / 越快越好", "modern_tip": "无论在口语还是商务邮件中都使用极其频繁，常被缩写并读作字母 'A-S-A-P' 或 /ˈeɪsæp/。", "example": {"en": "Please ask her to give me a call back as soon as possible.", "zh": "请让她尽快给我回个电话。"}}, {"word": "Hold on, please.", "phonetic": "[hoʊld ɑːn pliːz]", "pos": "phrase", "meaning": "请稍候 / 别挂断电话", "modern_tip": "接听电话、前去转接或查阅文件时的必备语，相当于 'Hang on a second' 或 'One moment please'。", "example": {"en": "Hold on, please. Let me transfer your call.", "zh": "请稍候别挂断，我来为您转接。"}}], "grammar": [{"num": "01", "title": "【电话英语两大雷区】This is vs. I am & Who's calling vs. Who are you", "formulas": ["报明自己身份：This is [名字] speaking.（绝对不说 I am...）", "询问对方是谁：Who's calling, please? / May I ask who is calling?（绝不能问 Who are you?）"], "desc": ["在看不见对方容貌的电话线两端，英语文化认为直接问 'Who are you?' 极度无礼，甚至像在质问；", "同理，自己介绍时用代词 'This' 指代目前正在发声的这个人，也是约定俗成的国际通信规则。"], "examples": ["Hello, this is Tom from customer support. Who's calling, please?", "May I ask who is calling, so I can announce you?"]}, {"num": "02", "title": "【对方不在时的三大经典应答句】", "formulas": ["人不在工位：He's not in today. / He's out at the moment.", "正在占线忙碌：She's on another line right now.", "探询回拨意愿：I'll ask him to call you back as soon as he returns."], "desc": ["熟练掌握接电话、留言及转接的句型闭环，是日常生存和外企商务沟通的核心技能之一。"], "examples": ["Mr. Davis is away from his desk. Can I take a message?", "I'll have her return your call before 5 PM."]}], "connected_speech": ["连读顺滑：'Hold on' 发生辅音与元音连读，读作 /ˈhoʊl-dɑːn/。", "弱读与缩读：'as soon as possible' 中的第一个 as 弱化为 /əz/，整句节奏快且清晰。", "声调对比：'May I speak to Bob, please?' 句尾升调，回答 'He's not in.' 句尾降调落地。"], "substitution": [], "exercises": []}, {"num": 10, "title_en": "Telephone Conversation II", "title_zh": "电话会话（二）", "type": "dialogue", "category": "日常高频情境口语", "tip": "在西方国家去诊所（Clinic）看病，绝大多数必须提前预约（Make an appointment），直接杀过去通常看不上。预约时直接报全名，并用 'I'd like to make an appointment to see Dr. [姓氏]'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hello, Dr. Chen's clinic. May I help you?", "zh": "哈啰，这里是陈医师诊所。我可以帮您什么忙吗？", "audio": "rumen_l10_01.mp3"}, {"speaker": "B", "en": "Yes, please. I'd like to make an appointment to see Dr. Chen.", "zh": "是的，麻烦你。我想约见陈医师。", "audio": "rumen_l10_02.mp3"}, {"speaker": "A", "en": "What's your name, please?", "zh": "请问尊姓大名？", "audio": "rumen_l10_03.mp3"}, {"speaker": "B", "en": "My name is Micky Chen.", "zh": "我的名字是陈米其。", "audio": "rumen_l10_04.mp3"}, {"speaker": "A", "en": "Is 4 o'clock in the afternoon OK?", "zh": "下午4点钟可以吗？", "audio": "rumen_l10_05.mp3"}, {"speaker": "B", "en": "That 's fine. Thank you.", "zh": "可以，谢谢你。", "audio": "rumen_l10_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "I would like to make a long-distance call to California, please.", "zh": "我想打一个长途电话到加州。", "audio": "rumen_l10_07.mp3"}, {"speaker": "B", "en": "Person to person or station to station?", "zh": "叫人的或叫号的？", "audio": "rumen_l10_08.mp3"}, {"speaker": "A", "en": "Station to station.", "zh": "叫号的。", "audio": "rumen_l10_09.mp3"}, {"speaker": "B", "en": "What's the number, please.", "zh": "请问电话号码几号？", "audio": "rumen_l10_10.mp3"}, {"speaker": "A", "en": "Area code 415,789 - 0277.", "zh": "区域号码为415，对方电话是789-0277。", "audio": "rumen_l10_11.mp3"}, {"speaker": "B", "en": "One moment, please.", "zh": "请稍候。", "audio": "rumen_l10_12.mp3"}]}], "reading": null, "vocab": [{"word": "make an appointment", "phonetic": "[meɪk ən əˈpɔɪntmənt]", "pos": "phrase", "meaning": "预约 / 约见（医生、律师、发型师等）", "modern_tip": "专业场合的正式预约叫 appointment；而订餐馆、订酒店、订机票用的则是 reservation / booking。", "example": {"en": "I'd like to make an appointment for a dental checkup.", "zh": "我想预约做一次牙科检查。"}}, {"word": "long-distance call", "phonetic": "[lɔːŋ ˈdɪstəns kɔːl]", "pos": "n.", "meaning": "长途电话", "modern_tip": "在传统电信年代，长途电话常区分地区区号（Area code），国际长途则叫 international call。", "example": {"en": "How do I make a long-distance call from my hotel room?", "zh": "在酒店房间里我该如何拨打长途电话？"}}, {"word": "area code", "phonetic": "[ˈeriə koʊd]", "pos": "n.", "meaning": "电话区号", "modern_tip": "美国电话号码由3位区号加7位电话号组成，如 (415) 789-0277。", "example": {"en": "What's the area code for San Francisco? -- It's 415.", "zh": "旧金山的区号是多少？-- 是415。"}}, {"word": "One moment, please.", "phonetic": "[wʌn ˈmoʊmənt pliːz]", "pos": "phrase", "meaning": "请稍候片刻", "modern_tip": "服务行业前台接待、接线员最高频的礼貌语，等同于 'Just a moment, please.'。", "example": {"en": "One moment, please. I'll check Dr. Chen's schedule.", "zh": "请稍等片刻，我来查一下陈医师的排班表。"}}], "grammar": [{"num": "01", "title": "【看病预约四大黄金句型】", "formulas": ["表达意图：I'd like to make an appointment to see Dr. [姓氏].", "协调时间：Is [时间] OK with you? / Does [时间] work for you?", "确认时间：That's fine. / That works for me.", "改期要求：Could we reschedule it for next Tuesday?"], "desc": ["在英语中，'I would like to'（简写为 I'd like to）比 'I want to' 礼貌谦逊百倍，是向服务人员提出诉求的标配句型。"], "examples": ["Does Thursday morning at 10 AM work for you? -- Yes, that's fine.", "I have an appointment with Dr. Chen at 4 o'clock."]}, {"num": "02", "title": "【长途通话历史术语解析】Person to person vs. Station to station", "formulas": ["叫人长途（Person-to-person）：接线员必须接通指定的那个人才开始计费（费用较高）", "叫号长途（Station-to-station）：对方电话一接通就计费，不管由谁接听（费用较低）"], "desc": ["这课展现了早期电信接线员服务的经典真实场景，了解这一背景能更好地理解教材中这两句专业问答的来龙去脉。"], "examples": ["A: Person to person or station to station?  B: Station to station, please."]}], "connected_speech": ["双元音与弱读：'make an appointment' 连读为 /ˈmeɪ-kən-ə-ˈpɔɪnt-mənt/，/k/ 自动连上 an 的元音。", "数字连读技巧：读电话号码 789-0277 时，数字 0 读作字母 'oh' /oʊ/；中间破折号处留半拍停顿。", "双声道修复：在之前的历史切片中，第1句与第4句左声道曾有静音问题，本次已使用双声道矩阵平衡算法全面修复！"], "substitution": [], "exercises": []}, {"num": 11, "title_en": "Telephone Conversation III", "title_zh": "电话会话（三）", "type": "dialogue", "category": "日常高频情境口语", "tip": "在海外酒店入住期间，客房送餐服务叫 'Room Service'，叫醒电话叫 'Morning call'（在欧美也极常称作 'Wake-up call'）。点餐时若厨房已下班，服务生会贴心告知冷餐供应。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hello, room service.", "zh": "哈啰，这里是客房服务中心。", "audio": "rumen_l11_01.mp3"}, {"speaker": "B", "en": "This is room 369. I'd like to order some food, please.", "zh": "这里是369号房。我想要点一些菜。", "audio": "rumen_l11_02.mp3"}, {"speaker": "A", "en": "I'm sorry, but the kitchen's closed.", "zh": "很抱歉，厨房已经关闭了。", "audio": "rumen_l11_03.mp3"}, {"speaker": "B", "en": "What do you have?", "zh": "那你们有什么？", "audio": "rumen_l11_04.mp3"}, {"speaker": "A", "en": "We have only sandwiches and drinks.", "zh": "我们只有三明治和饮料。", "audio": "rumen_l11_05.mp3"}, {"speaker": "B", "en": "That'll be fine. I'm starving.", "zh": "那也可以。我饿坏了。", "audio": "rumen_l11_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Hello, front desk. Can I help you?", "zh": "哈啰，这里是前台。我可以为您效劳吗？", "audio": "rumen_l11_07.mp3"}, {"speaker": "B", "en": "Can you give me a morning call, please?", "zh": "可不可以请你在早上打电话叫我起床？", "audio": "rumen_l11_08.mp3"}, {"speaker": "A", "en": "Sure. What time do you want to get up?", "zh": "当然。你想什么时候起床呢？", "audio": "rumen_l11_09.mp3"}, {"speaker": "B", "en": "Please call me at 6:00 AM.", "zh": "请在早上6点钟打电话来叫我。", "audio": "rumen_l11_10.mp3"}, {"speaker": "A", "en": "No problem.", "zh": "没问题。", "audio": "rumen_l11_11.mp3"}, {"speaker": "B", "en": "Thank you.", "zh": "谢谢。", "audio": "rumen_l11_12.mp3"}]}], "reading": null, "vocab": [{"word": "room service", "phonetic": "[ruːm ˈsɜːrvɪs]", "pos": "n.", "meaning": "客房送餐服务", "modern_tip": "酒店内点餐到客房的专有名词，拨打客房电话上的专门分机按键即可直通。", "example": {"en": "Can we get room service for breakfast tomorrow? -- Sure, dial extension 3.", "zh": "我们明早可以点客房送餐早餐吗？-- 当然，拨分机号3就行。"}}, {"word": "starving", "phonetic": "[ˈstɑːrvɪŋ]", "pos": "adj.", "meaning": "极度饥饿 / 饿坏了", "modern_tip": "比 hungry 强烈得多！口语中极其生动常用：'I'm starving!' 相当于‘我快饿扁了！’。", "example": {"en": "Let's grab a bite quickly, I'm starving!", "zh": "我们赶紧去吃口东西吧，我快饿死了！"}}, {"word": "morning call / wake-up call", "phonetic": "[ˈmɔːrnɪŋ kɔːl / ˈweɪk ʌp kɔːl]", "pos": "n.", "meaning": "叫醒电话 / 早晨叫醒服务", "modern_tip": "美语酒店中 'wake-up call' 使用频率极高，前台会在约定时间准点致电。", "example": {"en": "Could I get a wake-up call at 6:30 AM, please?", "zh": "能麻烦在早上六点半给我一个叫醒电话吗？"}}, {"word": "front desk", "phonetic": "[frʌnt desk]", "pos": "n.", "meaning": "前台 / 酒店总台", "modern_tip": "酒店大厅的核心服务中心，入住（check in）、退房（check out）、行李寄存均在此办理。", "example": {"en": "If you need extra towels, just call the front desk.", "zh": "如果你需要额外的毛巾，直接打给前台就行。"}}], "grammar": [{"num": "01", "title": "【酒店服务点餐句型】This is room... I'd like to order...", "formulas": ["自报房号：This is room [房号].（如 This is room 369.）", "点餐点物：I'd like to order some food, please.", "询问备选：What do you have available at this hour?"], "desc": ["致电酒店前台或客房部，第一句永远是自报房号，以便系统锁定账单和配送房门；", "当对方告知厨房下班时，'That'll be fine'（那也行/那就可以了）是表现通情达理的绝佳短语。"], "examples": ["This is room 502, could we get two bottles of water, please?", "Only cold sandwiches left? That'll be fine, thanks."]}, {"num": "02", "title": "【叫醒电话请求公式】Can you give me a wake-up call at...?", "formulas": ["句型：Could / Can you give me a morning call at [时间], please?", "回答肯定：Sure, no problem. What time do you need it?", "时间介词：在具体时刻前永远用介词 at（如 at 6:00 AM, at half past seven）。"], "desc": ["如果需要准时赶早班飞机或赶早会，在前台预约一个自动或人工叫醒电话是最稳妥的双重保险。"], "examples": ["Can you set a wake-up call for 7:00 sharp?", "I have a morning call scheduled for 6:15 AM."]}], "connected_speech": ["弱读与缩读：'That'll be fine' 中的 'That'll' 读作 /ˈðæ-tl/，/t/ 与 /l/ 形成舌侧爆破，听起来极其轻巧。", "时间介词连读：'at 6:00 AM' 连读为 /æt sɪks eɪ-ˈem/。", "口语强调重音：'I'm starving!' 重音强烈落在 star- 上，尾音拉低，生动传递饥饿感。"], "substitution": [], "exercises": []}, {"num": 12, "title_en": "Buying Things", "title_zh": "买东西", "type": "dialogue", "category": "日常高频情境口语", "tip": "在海外购物询价时，'How much is this?' 和 'How much does it cost?' 同样常用。当掏出一张百元大钞想破开时，地道说法是 'Do you have change for a hundred?'，千万不要说成 'Can you break my money?'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "How much does that pen cost?", "zh": "那枝笔要多少钱？", "audio": "rumen_l12_01.mp3"}, {"speaker": "B", "en": "It costs ten dollars.", "zh": "10块钱。", "audio": "rumen_l12_02.mp3"}, {"speaker": "A", "en": "That's very expensive. Do you have anything cheaper?", "zh": "那很贵。你们有没有比较便宜的？", "audio": "rumen_l12_03.mp3"}, {"speaker": "B", "en": "Sure. This pen is only two dollars.", "zh": "当然。这枝笔只要两块钱。", "audio": "rumen_l12_04.mp3"}, {"speaker": "A", "en": "Good. I'll take it.", "zh": "好。我就买这枝。", "audio": "rumen_l12_05.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "How much is this book?", "zh": "这本书要多少钱？", "audio": "rumen_l12_06.mp3"}, {"speaker": "B", "en": "It's seven dollars.", "zh": "七块钱。", "audio": "rumen_l12_07.mp3"}, {"speaker": "A", "en": "Do you have change for a hundred?", "zh": "你有零钱找开100块吗？", "audio": "rumen_l12_08.mp3"}, {"speaker": "B", "en": "No problem.", "zh": "没问题。", "audio": "rumen_l12_09.mp3"}, {"speaker": "A", "en": "OK. Here's the money.", "zh": "好。钱给你。", "audio": "rumen_l12_10.mp3"}, {"speaker": "B", "en": "Thank you. Here's the book and your change.", "zh": "谢谢。这儿是你的书和零钱。", "audio": "rumen_l12_11.mp3"}]}], "reading": null, "vocab": [{"word": "How much does it cost?", "phonetic": "[haʊ mʌtʃ dʌz ɪt kɔːst]", "pos": "phrase", "meaning": "这件东西多少钱？/ 它的造价是多少？", "modern_tip": "比单调的 'How much?' 更具正式感和完整度，cost 既可用作动词表示花费，也可用作名词表示成本。", "example": {"en": "How much does that leather jacket cost? -- It's $150.", "zh": "那件皮夹克要多少钱？-- 150美元。"}}, {"word": "change for...", "phonetic": "[tʃeɪndʒ fər]", "pos": "phrase", "meaning": "把大额钞票找开成零钱", "modern_tip": "日常生活神短语！想要破开100美元或50美元，直接问 'Do you have change for a fifty/hundred?'。", "example": {"en": "Can you give me change for a twenty? I need quarters for laundry.", "zh": "能帮我把20块钱换成零钱吗？我洗衣服需要25分硬币。"}}, {"word": "I'll take it.", "phonetic": "[aɪl teɪk ɪt]", "pos": "phrase", "meaning": "我就买这个了 / 我要了", "modern_tip": "选定商品后对店员说出的决定性买单神句，比 'I will buy this' 地道自然无数倍。", "example": {"en": "It fits you perfectly! -- Thanks, I'll take it.", "zh": "这件穿在你身上太合适了！-- 谢谢，那我就要这件了。"}}, {"word": "expensive vs. cheap", "phonetic": "[ɪkˈspensɪv / tʃiːp]", "pos": "adj.", "meaning": "昂贵的 vs. 便宜的", "modern_tip": "委婉表达想要更平价的商品时，用 'Do you have anything cheaper / more affordable?' 显得得体不寒酸。", "example": {"en": "That's a bit too expensive. Do you have a cheaper option?", "zh": "那稍微有点贵了。你们有性价比更高一点的选择吗？"}}], "grammar": [{"num": "01", "title": "【询价两大经典句式】How much is...? vs. How much does... cost?", "formulas": ["系动词句型（最常用）：How much is this book? -> It's seven dollars.", "行为动词句型（强调价格开销）：How much does that pen cost? -> It costs ten dollars."], "desc": ["两种提问在日常生活中完全互通；回答时注意货币单位：单一美元为 dollar，两元以上加复数 dollars。"], "examples": ["How much are these sunglasses? -- They are twenty-five dollars.", "How much does a round-trip ticket cost?"]}, {"num": "02", "title": "【找钱与零钱的双重含义】change 的万能用法", "formulas": ["作为找还的零钱：Here is your change.（这是找您的零钱）", "作为破开整钞：Do you have change for a hundred?（能找开一百元吗？）", "硬币散钱：Do you have any loose change?"], "desc": ["在收银台结账完毕时，店员递上商品和找零时常说 'Here is the book and your change.'（书和找零都在这儿）。"], "examples": ["Keep the change! (零钱不用找了！)", "I don't have enough change in the register right now."]}], "connected_speech": ["连读技巧：'How much does that pen cost' 中的 'much does' 连读为 /ˈmʌ-tʃdʌz/。", "介词弱读：'change for a hundred' 中的 for a 弱读连读为 /fər-ə/，读起来像 'fer-a'。", "决定性短语节奏：'I'll take it' 读作 /ˈaɪl ˈteɪ-kɪt/，/k/ 顺滑滑入 it 的元音。"], "substitution": [], "exercises": []}, {"num": 13, "title_en": "At the Restaurant", "title_zh": "在餐厅", "type": "dialogue", "category": "日常高频情境口语", "tip": "在西餐厅就餐，进门通常先等领位员（Host/Hostess），不要自己贸然找空桌坐下。点牛排时熟度是关键：Rare（一分熟）、Medium-rare（三分熟）、Medium（五分熟）、Medium-well（七分熟）、Well-done（全熟）。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Do you have a table for two?", "zh": "你们有两个人坐的餐桌吗？", "audio": "rumen_l13_01.mp3"}, {"speaker": "B", "en": "Yes. In the smoking or non-smoking section?", "zh": "有的。您是要在吸烟区或非吸烟区？", "audio": "rumen_l13_02.mp3"}, {"speaker": "A", "en": "Non-smoking. please.", "zh": "麻烦在非吸烟区。", "audio": "rumen_l13_03.mp3"}, {"speaker": "B", "en": "OK. This way, please.", "zh": "好的。请跟我这边走。", "audio": "rumen_l13_04.mp3"}, {"speaker": "A", "en": "May I have the menu?", "zh": "可以给我菜单吗？", "audio": "rumen_l13_05.mp3"}, {"speaker": "B", "en": "Sure. Here you are.", "zh": "当然。在这儿。", "audio": "rumen_l13_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "May I take your order now?", "zh": "我可以接受您的点菜了吗？", "audio": "rumen_l13_07.mp3"}, {"speaker": "B", "en": "Yes, please. I'll have the steak.", "zh": "是的，麻烦你。我要牛排。", "audio": "rumen_l13_08.mp3"}, {"speaker": "A", "en": "How would you like it?", "zh": "您的牛排要几分熟？", "audio": "rumen_l13_09.mp3"}, {"speaker": "B", "en": "Well-done, please.", "zh": "麻烦全熟。", "audio": "rumen_l13_10.mp3"}, {"speaker": "A", "en": "Would you like some dessert?", "zh": "您要不要来些甜点呢？", "audio": "rumen_l13_11.mp3"}, {"speaker": "B", "en": "No, thank you.", "zh": "不用了，谢谢。", "audio": "rumen_l13_12.mp3"}, {"speaker": "A", "en": "How about something to drink?", "zh": "那您要不要喝点什么呢？", "audio": "rumen_l13_13.mp3"}, {"speaker": "B", "en": "Hot coffee, please.", "zh": "麻烦热咖啡。", "audio": "rumen_l13_14.mp3"}]}], "reading": null, "vocab": [{"word": "table for two", "phonetic": "[ˈteɪbl fər tuː]", "pos": "phrase", "meaning": "两位用餐的桌子 / 两个人的座位", "modern_tip": "进餐厅领位员必问人数，回答直接说 'A table for two, please'（几个人就换几即可，如 a table for four）。", "example": {"en": "Good evening, table for three? -- Yes, please, non-smoking.", "zh": "晚上好，请问三位吗？-- 是的，麻烦安排无烟区。"}}, {"word": "May I take your order?", "phonetic": "[meɪ aɪ teɪk jʊr ˈɔːrdər]", "pos": "phrase", "meaning": "现在可以为您点餐了吗？", "modern_tip": "服务生前来点餐的标准礼貌开场白，客人点单回答用 'I'll have the...'。", "example": {"en": "Are you ready to order, or do you need a few more minutes?", "zh": "您二位准备好点餐了吗，还是需要再看几分钟？"}}, {"word": "well-done", "phonetic": "[ˌwel ˈdʌn]", "pos": "adj.", "meaning": "（牛排）全熟的 / 做得很好", "modern_tip": "点牛排问 'How would you like it cooked?' 时的经典熟度之一；此外也常用于表扬夸奖别人‘干得漂亮！’。", "example": {"en": "How would you like your steak? -- Medium-rare, please.", "zh": "您的牛排需要几分熟？-- 麻烦三分熟。"}}, {"word": "This way, please.", "phonetic": "[ðɪs weɪ pliːz]", "pos": "phrase", "meaning": "请跟我这边走", "modern_tip": "领位员、接待员引导客人入座时的经典短语，兼具专业与热情。", "example": {"en": "Your table is ready. Right this way, please.", "zh": "您的餐桌已准备好，请随我往这边走。"}}], "grammar": [{"num": "01", "title": "【西餐厅点菜点饮料万能公式】I'll have the...", "formulas": ["主食点单：I'll have the steak / pasta / salmon, please.", "饮品点单：I'll have hot coffee / iced tea, please.", "两人同时点：I'll have the burger, and she'll have the salad."], "desc": ["在餐厅点餐，老外最习惯用 'I'll have...'（我要一份……），既干脆利落又极其得体；", "也可以使用 'Could I get...?' 或 'I'd like to have...'，但尽量避免用生硬的 'I want...'。"], "examples": ["I'll have the grilled chicken with roasted vegetables.", "Can I get a glass of tap water to start with?"]}, {"num": "02", "title": "【牛排熟度五大层级】掌握菜单不再点错", "formulas": ["Rare：一分熟（中心鲜红温热）", "Medium-rare：三分熟（欧美食客的最爱与黄金推荐）", "Medium：五分熟（中心粉红带汁水）", "Medium-well：七分熟（中心微带肉粉）", "Well-done：全熟（完全熟透无血丝）"], "desc": ["服务生问 'How would you like it (cooked)?' 时，直接回答相应的熟度词块即可（如 'Medium, please.'）。"], "examples": ["How would you like your steak done? -- Medium, please."]}], "connected_speech": ["弱读连音：'table for two' 中的 for 弱读为 /fər/，读起来像 /ˈteɪ-bl fər tuː/。", "介词短语轻读：'In the non-smoking section' 重音落在 non-smoking 和 section 上。", "同化连音：'Would you like' 连读为 /ˈwʊ-dʒuː laɪk/，非常地道圆润。"], "substitution": [], "exercises": []}, {"num": 14, "title_en": "At the Clothing Store", "title_zh": "在服装店", "type": "dialogue", "category": "日常高频情境口语", "tip": "在国外服装店逛街试穿，'Can I try it on?'（我可以试穿吗？）是出镜率最高的黄金句型。问尺码用 'What size do you wear/take?'，衣服特价促销用 'on sale'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Can I have a look at that jacket, please?", "zh": "请问我可以看一下那件夹克吗？", "audio": "rumen_l14_01.mp3"}, {"speaker": "B", "en": "what size do you wear?", "zh": "你穿几号的呢？", "audio": "rumen_l14_02.mp3"}, {"speaker": "A", "en": "Extra large.", "zh": "特大号的。", "audio": "rumen_l14_03.mp3"}, {"speaker": "B", "en": "Here you are.", "zh": "在这里。", "audio": "rumen_l14_04.mp3"}, {"speaker": "A", "en": "Can I try it on?", "zh": "我可以试穿吗？", "audio": "rumen_l14_05.mp3"}, {"speaker": "B", "en": "Sure. Go ahead.", "zh": "当然。请便。", "audio": "rumen_l14_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "May I help you?", "zh": "我可以为你效劳吗？", "audio": "rumen_l14_07.mp3"}, {"speaker": "B", "en": "Yes, please. I'm looking for a necktie.", "zh": "是的，麻烦你，我正在找一条领带。", "audio": "rumen_l14_08.mp3"}, {"speaker": "A", "en": "Any special brand?", "zh": "要任何特别的品牌吗？", "audio": "rumen_l14_09.mp3"}, {"speaker": "B", "en": "No. Just something simple and not too expensive.", "zh": "不用。只要样式简单又不太贵就可以了。", "audio": "rumen_l14_10.mp3"}, {"speaker": "A", "en": "How about this one?", "zh": "这一条如何？", "audio": "rumen_l14_11.mp3"}, {"speaker": "B", "en": "That's fine. How much is it?", "zh": "可以。要多少钱呢？", "audio": "rumen_l14_12.mp3"}, {"speaker": "A", "en": "lt's only US $10 and it's on sale.", "zh": "只要10块美金，而且现在正在特价。", "audio": "rumen_l14_13.mp3"}, {"speaker": "B", "en": "OK. I'll take it. Thanks.", "zh": "好，我就把它买下了。谢谢。", "audio": "rumen_l14_14.mp3"}]}], "reading": null, "vocab": [{"word": "try it on", "phonetic": "[traɪ ɪt ɑːn]", "pos": "phrase", "meaning": "试穿（衣服、鞋子、帽子等）", "modern_tip": "代词 it 必须放在动词 try 和副词 on 中间（try it on），复数则为 try them on。", "example": {"en": "That dress looks gorgeous on the mannequin. Can I try it on?", "zh": "那条裙子穿在模特身上美极了。我可以试穿一下吗？"}}, {"word": "on sale", "phonetic": "[ɑːn seɪl]", "pos": "phrase", "meaning": "正在特价促销 / 打折", "modern_tip": "注意区分：'for sale' 意思是‘待售/出售中’；而 'on sale' 专指‘降价打折促销’！", "example": {"en": "All winter coats are 30% off, on sale this weekend only!", "zh": "所有冬季大衣七折特惠，仅限本周末促销！"}}, {"word": "extra large (XL)", "phonetic": "[ˌekstrə ˈlɑːrdʒ]", "pos": "n./adj.", "meaning": "特大号（服装尺码）", "modern_tip": "国际通用尺码：Small (S) -> Medium (M) -> Large (L) -> Extra Large (XL) -> XXL。", "example": {"en": "Do you have this hoodie in a medium? The large is too loose.", "zh": "这件卫衣你们有中号的吗？大号有点太宽松了。"}}, {"word": "look for...", "phonetic": "[lʊk fər]", "pos": "phrase", "meaning": "寻找 / 物色 / 寻找某种款式的商品", "modern_tip": "向导购员说明进店目的：'I'm looking for a winter jacket / a necktie.'。", "example": {"en": "May I help you? -- Yes, I'm looking for a formal dress for a wedding.", "zh": "有什么可以帮您的？-- 是的，我正在挑选参加婚礼的正装礼服。"}}], "grammar": [{"num": "01", "title": "【动副短语代词夹心规则】try it on vs. try them on", "formulas": ["单数衣物试穿：try it on（如夹克、裙子、衬衫）", "复数双重衣物试穿：try them on（如裤子 pants、鞋子 shoes、手套 gloves）", "禁止后置代词：绝对不能说 try on it 或 try on them（这是典型语法雷区）"], "desc": ["在英语的‘动词 + 副词’短语中，当宾语是人称代词（it/them）时，必须放在动词和副词正中间。"], "examples": ["Can I try this shirt on? / Can I try it on?", "These shoes look cool. Can I try them on?"]}, {"num": "02", "title": "【购物两大神级介词短语】on sale 与 for sale 的致命陷阱", "formulas": ["正在打折促销（减价）：on sale（如 It's only $10 and it's on sale!）", "非卖品 vs. 出售中：for sale（如 This vintage car is not for sale. 这辆老爷车是非卖品）"], "desc": ["记住：你想问店员这件东西打不打折，要问 'Is this on sale?'；如果你问 'Is this for sale?'，店员会以为你在问‘这件东西卖不卖’。"], "examples": ["Is this jacket on sale right now?", "Sorry, that display item is not for sale."]}], "connected_speech": ["连读技巧：'try it on' 中的 try-it-on 顺畅连为 /ˈtraɪ-ɪ-tɑːn/，美音中 /t/ 闪化为清脆的 /ɾ/。", "弱读现象：'What size do you wear' 中的 do you 弱化连读为 /də-jʊ/。", "介词连缀：'it's on sale' 连读为 /ˈɪ-tsɑːn seɪl/。"], "substitution": [], "exercises": []}, {"num": 15, "title_en": "At the Department Store", "title_zh": "在百货公司", "type": "dialogue", "category": "日常高频情境口语", "tip": "在海外百货商场挑礼物或试衣，店员常常会贴心提供礼品包装（Gift-wrap），试穿时找试衣间问 'Where is the fitting room?' 即可。量尺寸时店员常说 'Let me take your measurements'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Can I help you, please?", "zh": "能不能请你帮我一个忙呢？", "audio": "rumen_l15_01.mp3"}, {"speaker": "B", "en": "Sure. What can I do for you?", "zh": "当然。我能为你做什么？", "audio": "rumen_l15_02.mp3"}, {"speaker": "A", "en": "I'm looking for a gift for my son's birthday.", "zh": "我正在为我儿子物色一个生日礼物。", "audio": "rumen_l15_03.mp3"}, {"speaker": "B", "en": "How about this video game?", "zh": "这个电视游戏如何？", "audio": "rumen_l15_04.mp3"}, {"speaker": "A", "en": "That's a good idea. Can you gift-wrap it, please?", "zh": "那是个好主意。可以请你把它用礼品纸包装起来吗？", "audio": "rumen_l15_05.mp3"}, {"speaker": "B", "en": "Sure. No problem.", "zh": "当然。没问题。", "audio": "rumen_l15_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Excuse me. Do you have a blue dress my size?", "zh": "打扰一下，请问你这儿有合乎我尺寸的蓝色洋装吗？", "audio": "rumen_l15_07.mp3"}, {"speaker": "B", "en": "I think so. Let me take your measurements. OK. How about this dress over here?", "zh": "我想有的。让我量一下你的尺寸。好了，这边的这件洋装如何？", "audio": "rumen_l15_08.mp3"}, {"speaker": "A", "en": "Do you have a fitting room?", "zh": "你们有试衣间吗？", "audio": "rumen_l15_10.mp3"}, {"speaker": "B", "en": "It's in the corner over there.", "zh": "就在那边的角落里。", "audio": "rumen_l15_11.mp3"}, {"speaker": "A", "en": "Thank you.", "zh": "谢谢。", "audio": "rumen_l15_12.mp3"}, {"speaker": "B", "en": "You're welcome.", "zh": "不客气。", "audio": "rumen_l15_13.mp3"}]}], "reading": null, "vocab": [{"word": "gift-wrap", "phonetic": "[ˈɡɪft ræp]", "pos": "v./n.", "meaning": "礼品纸包装 / 用精美礼盒包装", "modern_tip": "买礼物送人时的必备要求：'Can you gift-wrap it, please?'，很多商场提供免费或低成本包装服务。", "example": {"en": "Could you gift-wrap this watch for me? It's an anniversary present.", "zh": "能帮我把这块手表包装成礼品吗？这是结婚纪念日礼物。"}}, {"word": "fitting room", "phonetic": "[ˈfɪtɪŋ ruːm]", "pos": "n.", "meaning": "试衣间 / 更衣室", "modern_tip": "商场专卖店中专用于试穿衣服的隔间，在美语中也可称作 dressing room。", "example": {"en": "Excuse me, where are the fitting rooms? -- Right around the corner.", "zh": "请问试衣间在哪里？-- 就在拐角处。"}}, {"word": "take measurements", "phonetic": "[teɪk ˈmeʒərmənts]", "pos": "phrase", "meaning": "量尺寸 / 测量三围或身量", "modern_tip": "导购员用软尺为你测量肩宽、胸围或腰围时的专业术语。", "example": {"en": "Let me take your measurements so we can find the perfect cut.", "zh": "让我量一下您的尺寸，这样我们能帮您选到最合身的剪裁。"}}, {"word": "my size", "phonetic": "[maɪ saɪz]", "pos": "phrase", "meaning": "适合我的尺码 / 我的号数", "modern_tip": "询问店里有没有自己穿的码：'Do you have this in my size?'。", "example": {"en": "I love the color! Do you have this sweater in my size?", "zh": "我好喜欢这颜色！这件毛衣有我的尺码吗？"}}], "grammar": [{"num": "01", "title": "【挑选礼物两大实战句型】", "formulas": ["说明目的：I'm looking for a gift for [对象]'s birthday / graduation.", "导购推荐：How about this video game / necklace / perfume?", "认可提议：That's a good idea! / That sounds wonderful!"], "desc": ["进店说明是为某人选购礼物时，导购会更精准地根据受赠人的年龄、喜好推荐适销热门款。"], "examples": ["I'm looking for a souvenir for my colleague back home.", "How about this handmade scarf? It's very popular."]}, {"num": "02", "title": "【方位指引三大经典句式】in the corner / around the corner / over there", "formulas": ["在那边角落里：It's in the corner over there.", "就在拐角处：It's right around the corner.", "在二楼：It's on the second floor, next to the elevator."], "desc": ["在百货商场问路时，'over there'（在那边）搭配手势指引是极高频的肢体与口语双重表达。"], "examples": ["The restrooms are in the corner over there.", "The shoe department is right on your left."]}], "connected_speech": ["辅音失爆：'gift-wrap' 中的 /t/ 不送气失去爆破，口型收紧直接滑入 /r/ 的卷舌音。", "闪音技巧：'fitting room' 中的 'fitting'，两个 /t/ 在美音中闪化读作轻快的 /ˈfɪ-ɾɪŋ/。", "介词缩连：'in the corner over there' 快速连缀，重音落在 corner 和 there 上。"], "substitution": [], "exercises": []}, {"num": 16, "title_en": "At the Shoe Store", "title_zh": "在鞋店", "type": "dialogue", "category": "日常高频情境口语", "tip": "在国外鞋店买鞋，英美鞋码系统（US/UK size）与国内的欧码（40、42等）完全不同。男鞋 US 8 相当于国内 41 码，女鞋 US 8 相当于 38-39 码。试穿觉得合脚时，脱口而出 'They fit like a glove' 或 'These are just right' 最地道。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Do you have these shoes in size 8?", "zh": "你们这些鞋有没有八号的？", "audio": "rumen_l16_01.mp3"}, {"speaker": "B", "en": "Sure. Here you are.", "zh": "当然。在这里。", "audio": "rumen_l16_02.mp3"}, {"speaker": "A", "en": "I'm sorry, but they are too small. Do you have a bigger pair?", "zh": "对不起，这双太小了。你们有比较大号的吗？", "audio": "rumen_l16_03.mp3"}, {"speaker": "B", "en": "Here. Try these on.", "zh": "这儿。试穿看看。", "audio": "rumen_l16_04.mp3"}, {"speaker": "A", "en": "Wow! These are just right.", "zh": "哇！这一双刚好。", "audio": "rumen_l16_05.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Excuse me. Can you show me some high heeled shoes?", "zh": "打扰一下。你能不能拿一些高跟鞋给我看？", "audio": "rumen_l16_06.mp3"}, {"speaker": "B", "en": "Sure. This way, please.", "zh": "当然。请这边走。", "audio": "rumen_l16_07.mp3"}, {"speaker": "A", "en": "These are too high. Do you have lower ones?", "zh": "这些太高了。你们有低一点的吗？", "audio": "rumen_l16_08.mp3"}, {"speaker": "B", "en": "How about these?", "zh": "那这些如何？", "audio": "rumen_l16_09.mp3"}, {"speaker": "A", "en": "They don't fit. Do you have smaller ones?", "zh": "这些不合脚。你们有小一点的吗？", "audio": "rumen_l16_10.mp3"}, {"speaker": "B", "en": "I'm afraid we don't have your size.", "zh": "恐怕我们没有你的尺寸。", "audio": "rumen_l16_11.mp3"}, {"speaker": "A", "en": "what a shame!", "zh": "真可惜！", "audio": "rumen_l16_12.mp3"}]}], "reading": null, "vocab": [{"word": "size 8 (shoes)", "phonetic": "[saɪz eɪt]", "pos": "n.", "meaning": "8号鞋码（美码）", "modern_tip": "买鞋问尺码标准短语：'Do you have these in a size 8 / 9.5?'。", "example": {"en": "Do you carry these running shoes in a size 9? -- Let me check the stock.", "zh": "这双跑鞋你们有9号的吗？-- 让我查查库存。"}}, {"word": "high-heeled shoes (heels)", "phonetic": "[ˌhaɪ ˈhiːld ʃuːz]", "pos": "n.", "meaning": "高跟鞋", "modern_tip": "日常口语中女性常常更简练地直接称之为 'heels'（如 'I love wearing heels'）。", "example": {"en": "Are you going to wear flats or heels to the banquet tonight?", "zh": "今晚的宴会你打算穿平底鞋还是高跟鞋？"}}, {"word": "just right", "phonetic": "[dʒʌst raɪt]", "pos": "phrase", "meaning": "刚刚好 / 正合适", "modern_tip": "不仅可以用来形容鞋子尺寸恰到好处，也可形容温度、调味、松紧舒适度正合心意。", "example": {"en": "How do they feel? -- Wow, these sneakers are just right!", "zh": "感觉怎么样？-- 哇，这双运动鞋穿上正合适！"}}, {"word": "They don't fit.", "phonetic": "[ðeɪ doʊnt fɪt]", "pos": "phrase", "meaning": "不合身 / 不合脚（尺寸不匹配）", "modern_tip": "注意区分：'fit' 专指【尺寸大小合不合适】；而 'suit' 专指【风格好不好看/衬不衬你】。", "example": {"en": "These boots don't fit; my toes are pinched. Do you have a wider pair?", "zh": "这双靴子不合脚，挤脚趾。你们有更宽一点的吗？"}}], "grammar": [{"num": "01", "title": "【鞋类单复数两大天规】These shoes are... vs. A pair of shoes is...", "formulas": ["直接指代复数：These shoes are too small. / Try these on.", "用 pair 计数：This pair of shoes is very comfortable. / Do you have a bigger pair?"], "desc": ["鞋子（shoes）、靴子（boots）、运动鞋（sneakers）天生成双成对，日常代指时永远用复数代词 they / them / these；", "试穿鞋子要说 'Try them on'，千万不能说成 'Try it on'（那是试穿单件上衣或裙子）。"], "examples": ["These shoes hurt my feet. Can I try a larger pair?", "Do you have these in black? -- Yes, here is a size 8 in black."]}, {"num": "02", "title": "【挑选鞋款对比句型】lower / higher / bigger / smaller", "formulas": ["跟太高想要低跟：Do you have lower ones? / Do you have low-heeled shoes?", "尺寸不合想要大小码：Do you have a half size bigger / smaller?"], "desc": ["代词 ones 代指前面的复数 shoes，避免重复；", "半码在英语中称为 half size（如 'Can I get a half size up?' 能换大半码吗？）。"], "examples": ["These heels are a bit too high for walking. Do you have lower ones?", "They feel a little tight. I think I need a half size up."]}], "connected_speech": ["连读顺滑：'These are just right' 读作 /ˈðiː-zər dʒʌst raɪt/，/z/ 与 are 自然衔接。", "代词同化：'Try these on' 读作 /ˈtraɪ-ðiː-zɑːn/。", "失去爆破：'don't fit' 中的 /t/ 失去爆破，口型紧绷瞬间过渡到 /f/。"], "substitution": [], "exercises": []}, {"num": 17, "title_en": "At the Bookstore", "title_zh": "在书店", "type": "dialogue", "category": "日常高频情境口语", "tip": "在海外书店买书，'paperback'（平装本，轻便平价）和 'hardcover'（精装本，硬壳典藏厚重）是书架上最常见的一书两版。新书发售多为精装，几个月后推平装。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me. Do you have A Tale of Two Cities?", "zh": "打扰一下。你们有《双城记》这本书吗？", "audio": "rumen_l17_01.mp3"}, {"speaker": "B", "en": "Who is the author?", "zh": "作者是谁？", "audio": "rumen_l17_02.mp3"}, {"speaker": "A", "en": "Charles Dickens.", "zh": "查尔斯·狄更斯。", "audio": "rumen_l17_03.mp3"}, {"speaker": "B", "en": "Sorry, we're sold out right now. Please come back next week.", "zh": "很抱歉，我们现在卖完了。请下个星期再来。", "audio": "rumen_l17_04.mp3"}, {"speaker": "A", "en": "OK. Thanks!", "zh": "好的。多谢！", "audio": "rumen_l17_05.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Do you have a good English-Chinese dictionary?", "zh": "你们有没有好的英汉词典？", "audio": "rumen_l17_06.mp3"}, {"speaker": "B", "en": "Sure. How about this one?", "zh": "当然有。这一本如何？", "audio": "rumen_l17_07.mp3"}, {"speaker": "A", "en": "Is this the latest edition?", "zh": "这是最新版本吗？", "audio": "rumen_l17_08.mp3"}, {"speaker": "B", "en": "Yes. We have both the paperback and the hardcover.", "zh": "是的。我们有平装本和精装本。", "audio": "rumen_l17_09.mp3"}, {"speaker": "A", "en": "What's the difference?", "zh": "有什么差别呢？", "audio": "rumen_l17_10.mp3"}, {"speaker": "B", "en": "The hardcover is more expensive.", "zh": "精装本比较贵。", "audio": "rumen_l17_11.mp3"}, {"speaker": "A", "en": "Oh! I see. I'll have the paperback, please.", "zh": "噢！我明白了。请给我平装本的。", "audio": "rumen_l17_12.mp3"}]}], "reading": null, "vocab": [{"word": "paperback vs. hardcover", "phonetic": "[ˈpeɪpərbæk / ˈhɑːrdkʌvər]", "pos": "n.", "meaning": "平装书 vs. 精装书（硬皮书）", "modern_tip": "购书核心术语。学生和日常阅读多选 paperback，馈赠与收藏多买 hardcover。", "example": {"en": "I travel a lot, so I always prefer the lightweight paperback edition.", "zh": "我经常出差旅行，所以我总是更喜欢轻便的平装本。"}}, {"word": "sold out", "phonetic": "[soʊld aʊt]", "pos": "adj./phrase", "meaning": "售罄 / 卖完了 / 脱销", "modern_tip": "不仅用于书籍卖光，电影票（sold out）、演唱会门票、爆款商品抢光全用它。", "example": {"en": "We are completely sold out of that novel. More copies arrive on Monday.", "zh": "那本小说我们彻底卖断货了。周一会有更多新书到货。"}}, {"word": "latest edition", "phonetic": "[ˈleɪtɪst ɪˈdɪʃn]", "pos": "n.", "meaning": "最新版本 / 最新一版", "modern_tip": "买教材、词典或工具书时的必备问句：'Is this the latest edition?'。", "example": {"en": "Make sure you purchase the latest edition of the textbook for this class.", "zh": "请务必购买本门课程的最新版教材。"}}, {"word": "author", "phonetic": "[ˈɔːθər]", "pos": "n.", "meaning": "作者 / 作家", "modern_tip": "书店店员帮忙在电脑中检索书名时常问：'Who is the author?'。", "example": {"en": "Can you recommend a great mystery novel? Who is your favorite author?", "zh": "能推荐一本精彩的悬疑小说吗？你最喜欢的作者是谁？"}}], "grammar": [{"num": "01", "title": "【两项兼备经典句式】both... and...", "formulas": ["结构：We have both [A] and [B].（两者兼有）", "示例：We have both the paperback and the hardcover."], "desc": ["在表达两者都具备时，'both... and...' 结构工整优美，用于书店、餐厅或功能介绍中极其自然；", "询问两者差异用万能句型：'What's the difference between A and B?'。"], "examples": ["The app is available on both iOS and Android.", "What's the difference between the standard and deluxe versions?"]}, {"num": "02", "title": "【形容词比较级在购物中的应用】", "formulas": ["多音节词比较级：more + 形容词（如 more expensive / more popular）", "单音节词比较级：词尾加 -er（如 cheaper / bigger / thinner）"], "desc": ["表达'精装本更昂贵'用 'The hardcover is more expensive'；", "买平装本用决定句型：'I'll have the paperback, please.'。"], "examples": ["Digital books are usually cheaper than printed ones.", "This edition includes more practical case studies."]}], "connected_speech": ["连读技巧：'sold out' 连读为 /ˈsoʊl-daʊt/，/d/ 音清晰饱满连入 out。", "弱读现象：'both the paperback and the hardcover' 中的 and the 极快弱化为 /ən-ðə/。", "作者专有名词重音：'Charles Dickens' 中的 Dickens 重音在前音节 /ˈdɪ-kɪnz/。"], "substitution": [], "exercises": []}, {"num": 18, "title_en": "Taking a Taxi", "title_zh": "搭出租车", "type": "dialogue", "category": "日常高频情境口语", "tip": "在国外乘坐出租车（Cab / Taxi）或 Uber / Lyft，上车司机通常问 'Where to?'（去哪儿呀？）。下车付现金时如果不需要找零，递过钞票说一声极其潇洒的 'Keep the change!' 即可，这也是欧美普遍的小费文化体现。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Where to, ma'am?", "zh": "小姐，你要到哪里去？", "audio": "rumen_l18_01.mp3"}, {"speaker": "B", "en": "The train station, please.", "zh": "麻烦到火车站。", "audio": "rumen_l18_02.mp3"}, {"speaker": "A", "en": "Here we are, ma'am.", "zh": "（抵达后） 小姐，到了。", "audio": "rumen_l18_03.mp3"}, {"speaker": "B", "en": "How much do I owe you?", "zh": "要给你多少钱？", "audio": "rumen_l18_04.mp3"}, {"speaker": "A", "en": "It's 135 Yuan on the meter,", "zh": "里程表上是135元。", "audio": "rumen_l18_05.mp3"}, {"speaker": "B", "en": "Here's 150 Yuan, keep the change.", "zh": "这里是150元钱。零钱不用找了。", "audio": "rumen_l18_06.mp3"}, {"speaker": "A", "en": "Thanks!", "zh": "多谢！", "audio": "rumen_l18_07.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "To the airport, please.", "zh": "麻烦到机场。", "audio": "rumen_l18_08.mp3"}, {"speaker": "B", "en": "The international or domestic one?", "zh": "国际机场还是国内机场？", "audio": "rumen_l18_09.mp3"}, {"speaker": "A", "en": "The international airport.", "zh": "国际机场。", "audio": "rumen_l18_10.mp3"}, {"speaker": "B", "en": "Got it!", "zh": "知道了。", "audio": "rumen_l18_11.mp3"}, {"speaker": "A", "en": "Could you speed up, please? I don't want to miss my flight.", "zh": "麻烦能请你开快一点吗？我不想误了我的班机。", "audio": "rumen_l18_12.mp3"}, {"speaker": "B", "en": "What time's your flight?", "zh": "你的班机是几点？", "audio": "rumen_l18_13.mp3"}, {"speaker": "A", "en": "10:45 pm.", "zh": "晚上10点45分。", "audio": "rumen_l18_14.mp3"}, {"speaker": "B", "en": "Don't worry! I'll get you there in time.", "zh": "别担心！我会及时把你送到那儿去。", "audio": "rumen_l18_15.mp3"}]}], "reading": null, "vocab": [{"word": "Where to?", "phonetic": "[wer tuː]", "pos": "phrase", "meaning": "去哪儿？/ 到哪里？", "modern_tip": "出租车司机最地道的超简开场问话（完整为 Where are you going to?），乘客回答直接说目的地 + please 即可。", "example": {"en": "Hop in! Where to? -- Central Park, please.", "zh": "快上车！去哪儿？-- 麻烦到中央公园。"}}, {"word": "Keep the change.", "phonetic": "[kiːp ðə tʃeɪndʒ]", "pos": "phrase", "meaning": "零钱不用找了 / 不用找零（当小费）", "modern_tip": "打车、餐厅或外卖结账时极为经典的惯用语，大方得体且省却数硬币的繁琐。", "example": {"en": "The fare is $18. Here's a twenty, keep the change!", "zh": "车费18块。给你一张20的，不用找了！"}}, {"word": "speed up", "phonetic": "[spiːd ʌp]", "pos": "phrase", "meaning": "加速 / 开快一点", "modern_tip": "赶时间时请司机开快的礼貌说法：'Could you speed up a bit, please?'，相反慢一点是 slow down。", "example": {"en": "Can we speed up a little? I'm running behind schedule.", "zh": "能稍微开快一点吗？我快要赶不上时间了。"}}, {"word": "miss my flight", "phonetic": "[mɪs maɪ flaɪt]", "pos": "phrase", "meaning": "误机 / 错过航班", "modern_tip": "赶往机场时极其抓狂的高频心声：'I don't want to miss my flight!'。", "example": {"en": "Traffic is terrible! If we don't move soon, we'll miss our flight.", "zh": "堵车太严重了！如果我们还不动弹，就要误机了。"}}], "grammar": [{"num": "01", "title": "【打车目的地与航站楼区分】international vs. domestic", "formulas": ["国际机场/航站楼：the international terminal / airport", "国内机场/航站楼：the domestic terminal / airport"], "desc": ["去大城市的机场（如纽约肯尼迪、洛杉矶或希思罗），司机必须搞清是国际航线还是国内航线，否则跑错航站楼可能会耽误大半小时。", "听到司机追问 'The international or domestic one?'，立刻清晰回应其中之一。"], "examples": ["Please take me to Terminal 3, international departures.", "I'm catching a domestic flight to Boston."]}, {"num": "02", "title": "【下车结账两大事先问话】How much do I owe you? & On the meter", "formulas": ["询问应付车费：How much do I owe you?（我欠您多少车费？）", "按打表计费：It's 135 on the meter."], "desc": ["口语中老外非常喜欢用 owe（欠）来问车费或餐费：'How much do I owe you?'（我该给你多少钱？），比 'How much money should I give you' 自然得多。"], "examples": ["We're here! How much do I owe you, driver? -- That'll be twenty-two dollars.", "Always make sure the taxi driver turns on the meter."]}], "connected_speech": ["连读技巧：'speed up' 连读为 /ˈspiː-dʌp/，/d/ 饱满弹入 up。", "介词连读：'in time' 读作 /ɪn ˈtaɪm/，重音在 time 上，表示在时限之前及时赶到。", "失去爆破：'I don't want to miss' 中的 don't 和 want 尾音 /t/ 全部弱化不爆破，语速流畅飞快。"], "substitution": [], "exercises": []}, {"num": 19, "title_en": "Booking a Room", "title_zh": "订房间", "type": "dialogue", "category": "日常高频情境口语", "tip": "在海外订酒店，房型名称是核心：'Single room'（单人间/单人床）、'Double room'（大床双人间，一张大双人床）、'Twin room'（标准双人间，两张单人床）。房间订光了叫 'fully booked'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me. Do you have a single room?", "zh": "请问一下，你们有单人房吗？", "audio": "rumen_l19_01.mp3"}, {"speaker": "B", "en": "Sorry. We're fully booked. The only room available at the moment is a twin room.", "zh": "很抱歉，我们全订满了。目前惟一的空房是双人房。", "audio": "rumen_l19_02.mp3"}, {"speaker": "A", "en": "OK. I'll take it.", "zh": "好，我就要双人房。", "audio": "rumen_l19_03.mp3"}, {"speaker": "B", "en": "May I have your name, please?", "zh": "请问尊姓大名？", "audio": "rumen_l19_04.mp3"}, {"speaker": "A", "en": "I'm John Li.", "zh": "我是李约翰。", "audio": "rumen_l19_05.mp3"}, {"speaker": "B", "en": "How many days do you want to stay?", "zh": "您想要住几天呢？", "audio": "rumen_l19_06.mp3"}, {"speaker": "A", "en": "Five days.", "zh": "五天。", "audio": "rumen_l19_07.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Excuse me. My name is Jack Wu. I'd like to book a room.", "zh": "麻烦你，我的名字是吴杰克，我想要订房间。", "audio": "rumen_l19_08.mp3"}, {"speaker": "B", "en": "Single or double?", "zh": "您要单人房还是双人房？", "audio": "rumen_l19_09.mp3"}, {"speaker": "A", "en": "what are the rates?", "zh": "房价怎么算？", "audio": "rumen_l19_10.mp3"}, {"speaker": "B", "en": "l It's US $100 for a single and Us $150 for a double.", "zh": "单人房是100块美金，而双人房是150块美金。", "audio": "rumen_l19_11.mp3"}, {"speaker": "A", "en": "I'll take a single for 3 days.", "zh": "我要一间单人房的，住三天。", "audio": "rumen_l19_12.mp3"}, {"speaker": "B", "en": "OK. Just come to the front desk at the lobby.", "zh": "好。请到大厅的柜台来就行了。", "audio": "rumen_l19_13.mp3"}, {"speaker": "A", "en": "Ok. I'll arrive tomorrow.", "zh": "好的。我明天到。", "audio": "rumen_l19_14.mp3"}, {"speaker": "B", "en": "See you then.", "zh": "到时候见。", "audio": "rumen_l19_15.mp3"}]}], "reading": null, "vocab": [{"word": "fully booked", "phonetic": "[ˈfʊli bʊkt]", "pos": "adj.", "meaning": "全部订满了 / 满房 / 客满", "modern_tip": "酒店前台或热门餐厅告知客满的标准说法，相当于 'no vacancy' 或 'sold out'。", "example": {"en": "We're fully booked for the holiday weekend, sorry!", "zh": "我们长假周末所有的房间都订满了，实在不好意思！"}}, {"word": "single vs. double vs. twin", "phonetic": "[ˈsɪŋɡl / ˈdʌbl / twɪn]", "pos": "n.", "meaning": "单人房 vs. 大床双人房 vs. 双床双人间", "modern_tip": "千万注意区分：double 是指睡两人的大双人床（Queen/King bed），而 twin 是两张独立单人床（适合同事/朋友同住）。", "example": {"en": "My colleague and I need a twin room with two separate beds.", "zh": "我和我同事需要一间带两张独立单人床的标准双人间。"}}, {"word": "rates", "phonetic": "[reɪts]", "pos": "n. pl.", "meaning": "房价 / 收费标准 / 费率", "modern_tip": "询问酒店住一晚多少钱的标准专业用词：'What are your nightly rates?'。", "example": {"en": "What are the rates for a deluxe suite in July?", "zh": "七月份豪华套房的每晚房价是多少？"}}, {"word": "lobby", "phonetic": "[ˈlɑːbi]", "pos": "n.", "meaning": "大堂 / 酒店大厅", "modern_tip": "酒店的核心公共区域，办理手续的柜台就在大厅（'front desk at the lobby'）。", "example": {"en": "I'll meet you downstairs in the hotel lobby at 8:00 sharp.", "zh": "我八点整在酒店一楼大堂等您。"}}], "grammar": [{"num": "01", "title": "【酒店房型选择三大问答】", "formulas": ["问询空房：Do you have any rooms available for tonight?", "前台确认房型：Single, double, or twin room?", "确认接单：I'll take a single for three days / three nights."], "desc": ["在酒店预订中，计算居住时长通常以'夜数'（nights）或'天数'（days）计量，如 'a 3-night stay'（住三晚）。"], "examples": ["Do you have a non-smoking double room for three nights?", "The only room available at the moment is a junior suite."]}, {"num": "02", "title": "【房价与费用询问公式】What are the rates?", "formulas": ["问房价：What are your room rates? / How much is it per night?", "报价格：It's US $100 for a single and US $150 for a double.", "问税费及早餐：Does the rate include breakfast and tax?"], "desc": ["在国外订房问完价格后，常紧跟一句 'Does the rate include breakfast?'（房费含早吗？），非常实用。"], "examples": ["What are the rates during the peak tourist season?", "Our special corporate rate is $120 plus tax."]}], "connected_speech": ["弱读与同化：'available at the moment' 快速连缀连读为 /əˈveɪ-lə-blət ðə ˈmoʊ-mənt/。", "弱读介词：'It's US $100 for a single' 中的 for a 弱读为 /fər-ə/。", "道别节奏：'See you then' 重音在 then 上，干脆利落收尾。"], "substitution": [], "exercises": []}, {"num": 20, "title_en": "Checking into a Hotel", "title_zh": "办理住宿手续", "type": "dialogue", "category": "日常高频情境口语", "tip": "到达酒店办理入住手续叫 'Check in'，退房叫 'Check out'。前台必做两件事：填登记表（Fill out this form）和出示证件（Passport/ID）。押金支付方式问 'Pay by cash or charge?'（付现金还是刷信用卡？）。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Good morning. I'm Mr. Jack Wu. I have a reservation for a suite.", "zh": "早安。我是吴杰克。我订了一间套房。", "audio": "rumen_l20_01.mp3"}, {"speaker": "B", "en": "Oh, yes, Mr. Wu. Please fill out this form.", "zh": "哦，有的，吴先生。请填一下这张表格。", "audio": "rumen_l20_02.mp3"}, {"speaker": "A", "en": "Here you are.", "zh": "拿去吧。", "audio": "rumen_l20_03.mp3"}, {"speaker": "B", "en": "will you pay by cash or charge?", "zh": "您要付现金还是刷卡？", "audio": "rumen_l20_04.mp3"}, {"speaker": "A", "en": "Do you take traveler's checks?", "zh": "你们收旅行支票吗？", "audio": "rumen_l20_05.mp3"}, {"speaker": "B", "en": "Certainly.", "zh": "当然收。", "audio": "rumen_l20_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Excuse me. I'd like to check in, please. My name is Jack Wu.", "zh": "打扰一下，我想办理住宿手续，我是吴杰克。", "audio": "rumen_l20_07.mp3"}, {"speaker": "B", "en": "One moment, please. Oh, yes. You have a reservation for a single room, right?", "zh": "请稍等一下。哦，有的。你订了一间单人房，对不对？", "audio": "rumen_l20_08.mp3"}, {"speaker": "A", "en": "That's right.", "zh": "没错。", "audio": "rumen_l20_09.mp3"}, {"speaker": "B", "en": "May I have a look at your passport?", "zh": "我可以看一下您的护照吗？", "audio": "rumen_l20_10.mp3"}, {"speaker": "A", "en": "Here you go.", "zh": "拿去吧。", "audio": "rumen_l20_11.mp3"}, {"speaker": "B", "en": "OK. You're booked in Room 609. Do you have any luggage?", "zh": "好了。您预订的是609号房。您有行李吗？", "audio": "rumen_l20_12.mp3"}, {"speaker": "A", "en": "Yes. These two suitcases.", "zh": "有的。就这两个手提箱。", "audio": "rumen_l20_13.mp3"}, {"speaker": "B", "en": "No problem. The bellboy will take them and show you to your room.", "zh": "没问题。服务生会拿行李并带您到房间去。", "audio": "rumen_l20_14.mp3"}]}], "reading": null, "vocab": [{"word": "check in", "phonetic": "[tʃek ɪn]", "pos": "v./n.", "meaning": "办理入住手续 / 报到登记", "modern_tip": "既可作动词（'I'd like to check in'），也可作名词（'Check-in is after 3 PM'）。", "example": {"en": "Hi, I have a reservation and I'd like to check in, please.", "zh": "您好，我有预订，想办理入住手续。"}}, {"word": "suite", "phonetic": "[swiːt]", "pos": "n.", "meaning": "套房（带起居室和独立卧室的豪华房型）", "modern_tip": "【发音大坑】这个单词读音完全等同于 sweet（甜蜜的，读作 /swiːt/），绝不能按拼写读成 suit（西装）！", "example": {"en": "They upgraded us to the presidential suite for our honeymoon!", "zh": "因为我们度蜜月，他们给我们免费升级到了总统套房！"}}, {"word": "bellboy / porter", "phonetic": "[ˈbelbɔɪ / ˈpɔːrtər]", "pos": "n.", "meaning": "行李员 / 门童", "modern_tip": "在星级酒店帮你推行李车、送行李进房间的服务人员，通常在送到房间后需给少许小费（如1-2美元/件）。", "example": {"en": "The bellboy will bring your suitcases up to Room 609 shortly.", "zh": "行李员很快会把您的行李箱送到609号房。"}}, {"word": "pay by cash or charge", "phonetic": "[peɪ baɪ kæʃ ɔːr tʃɑːrdʒ]", "pos": "phrase", "meaning": "付现金还是刷信用卡？", "modern_tip": "charge 在这里是 'charge to credit card'（记账/刷卡）的口语简缩形式，现代也常说 'Cash or card?'。", "example": {"en": "Will that be cash or card today, sir? -- Credit card, please.", "zh": "先生今天付现金还是刷卡？-- 麻烦刷信用卡。"}}], "grammar": [{"num": "01", "title": "【酒店入住前台四部曲】", "formulas": ["第一步（核实预订）：I have a reservation under the name [名字].", "第二步（填写表单）：Please fill out this registration form.", "第三步（证件查验）：May I see / have a look at your passport?", "第四步（分配钥匙）：Here is your room key. You're in room [房号]."], "desc": ["在欧美酒店办理入住时，前台一定会要求提供信用卡预授权作为押金（Security deposit）；", "递给对方护照或证件时，地道说法是 'Here you go' 或 'Here you are'。"], "examples": ["I have a booking for a deluxe room under John Smith.", "Here's your keycard. Breakfast is served from 7 to 10 in the morning."]}, {"num": "02", "title": "【递交物品三大神短语】Here you are vs. Here you go vs. There you go", "formulas": ["Here you are：最经典标准的'给你 / 拿去吧'", "Here you go：美语极度地道的日常版本（递咖啡、递证件、给找零）", "There you go：操作完成、递交物品或鼓励别人'这不就做成了嘛'"], "desc": ["这三个短语在现代英语国家几乎每天都要用数十次，随手递任何东西给他人时说一句，尽显母语者般的丝滑流畅。"], "examples": ["Can you pass the salt, please? -- Here you go!", "Here you are, your passport and boarding pass."]}], "connected_speech": ["动副连读：'check in' 连读为 /ˈtʃe-kɪn/，/k/ 音与 in 紧密无缝咬合。", "代词连读：'fill out this form' 连读为 /ˈfɪ-laʊt ðɪs fɔːrm/。", "发音纠偏：'suite' 务必发清脆的双元音 /swiːt/（跟 sweet 一模一样），切勿发错。"], "substitution": [], "exercises": []}, {"num": 21, "title_en": "Changing Money", "title_zh": "换钱", "type": "dialogue", "category": "日常高频情境口语", "tip": "出国在银行或货币兑换店（Currency Exchange / Bureau de Change）换钱，先看门头屏幕上的汇率（Exchange rate）。想要大钞还是小钞零钱，店员会问 'How do you want your money?'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "I would like to cash these traveler's checks, please.", "zh": "麻烦你，我想把这些旅行支票换成现金。", "audio": "rumen_l21_01.mp3"}, {"speaker": "B", "en": "How much do you have?", "zh": "你有多少？", "audio": "rumen_l21_02.mp3"}, {"speaker": "A", "en": "Five hundred US dollars.", "zh": "500美元。", "audio": "rumen_l21_03.mp3"}, {"speaker": "B", "en": "Do you have any identification?", "zh": "你有任何身分证明文件吗？", "audio": "rumen_l21_04.mp3"}, {"speaker": "A", "en": "Will my passport do?", "zh": "我的护照可以吗？", "audio": "rumen_l21_05.mp3"}, {"speaker": "B", "en": "That'll be fine.", "zh": "那就可以了。", "audio": "rumen_l21_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "What's the exchange rate for US dollars, please?", "zh": "请问美元的汇率是多少？", "audio": "rumen_l21_07.mp3"}, {"speaker": "B", "en": "Which currency do you want to change your money into?", "zh": "你要把钱换成哪一种货币？", "audio": "rumen_l21_08.mp3"}, {"speaker": "A", "en": "Hong Kong dollars, please.", "zh": "港币，麻烦你。", "audio": "rumen_l21_09.mp3"}, {"speaker": "B", "en": "It's 7.89 Hong Kong dollars to 1 US dollar.", "zh": "汇率是7.89港币兑1美元。", "audio": "rumen_l21_10.mp3"}, {"speaker": "A", "en": "Can you change US $100?", "zh": "你能换100美元吗？", "audio": "rumen_l21_11.mp3"}, {"speaker": "B", "en": "How do you want your money?", "zh": "你要多少面额的钱？", "audio": "rumen_l21_12.mp3"}, {"speaker": "A", "en": "Seven hundreds, eight tens and the rest in change, please.", "zh": "七张100元，八张10元，其余的换成零钱。", "audio": "rumen_l21_13.mp3"}, {"speaker": "B", "en": "No problem.", "zh": "没问题。", "audio": "rumen_l21_14.mp3"}]}], "reading": null, "vocab": [{"word": "exchange rate", "phonetic": "[ɪksˈtʃeɪndʒ reɪt]", "pos": "n.", "meaning": "汇率 / 兑换率", "modern_tip": "外汇核心词：'What's the exchange rate for US dollars today?'。", "example": {"en": "What is the current exchange rate from Euros to US Dollars?", "zh": "现在的欧元对美元汇率是多少？"}}, {"word": "cash traveler's checks", "phonetic": "[kæʃ ˈtrævələrz tʃeks]", "pos": "phrase", "meaning": "把旅行支票兑成现金", "modern_tip": "动词 cash 在这里作及物动词使用，意思是‘兑现/兑成现金’。", "example": {"en": "Where is the nearest bank where I can cash my traveler's checks?", "zh": "最近能帮我把旅行支票换成现金的银行在哪？"}}, {"word": "identification (ID)", "phonetic": "[aɪˌdentɪfɪˈkeɪʃn]", "pos": "n.", "meaning": "身分证明文件 / 证件", "modern_tip": "日常口语几乎全部简写为字母 'ID'（如 'Do you have a photo ID?'）。在国外护照（Passport）是最权威的国际 ID。", "example": {"en": "You'll need a valid photo ID to pick up this package.", "zh": "你需要出示有效的带照片证件来领取这个包裹。"}}, {"word": "in change", "phonetic": "[ɪn tʃeɪndʒ]", "pos": "phrase", "meaning": "以零钱/散钞的形式", "modern_tip": "换钱时要求一部分大钞、其余给零钱：'and the rest in change, please'。", "example": {"en": "Could I get ten dollars in change? I need dollar bills.", "zh": "能给我换十块钱的零钱吗？我需要一美元面额的纸币。"}}], "grammar": [{"num": "01", "title": "【外币兑换万能句式】change [币种A] into [币种B]", "formulas": ["结构：change / convert [货币A] into [货币B]", "提问目标：Which currency do you want to change your money into?", "回答示例：I'd like to change 500 US dollars into Hong Kong dollars."], "desc": ["介词 into 表示‘形态转化’，从一种货币形态转换到另一种货币形态；", "汇率比值表达法：'It's 7.89 Hong Kong dollars to 1 US dollar'（7.89港币兑1美元，注意用介词 to）。"], "examples": ["Can you change these British Pounds into Japanese Yen?", "The bank charges a 2% commission on currency conversions."]}, {"num": "02", "title": "【钞票面额挑选公式】How do you want your money?", "formulas": ["大钞面额：[数字] hundreds（几张百元大钞）/ [数字] twenties（几张二十元）", "小钞零钱：and the rest in small bills / change（其余给小钞）"], "desc": ["柜员问你 'How do you want your bills?' 时，直接说明配置要求，比如：'Two fifties, five twenties, and the rest in tens'（两张五十、五张二十，其余全给十元钞）。"], "examples": ["How do you want your cash? -- In hundred-dollar bills, please.", "Give me five tens and the rest in quarters, please."]}], "connected_speech": ["连读同化：'cash these' 连读，/ʃ/ 音顺滑过渡到浊齿擦音 /ð/。", "介词弱读：'Hong Kong dollars to 1 US dollar' 中的 to 弱化为 /tə/。", "情态动词弱连：'Will my passport do?' 句尾升调，do 表达‘行不行/管不管用’。"], "substitution": [], "exercises": []}, {"num": 22, "title_en": "Booking an Airline Ticket", "title_zh": "订机票", "type": "dialogue", "category": "日常高频情境口语", "tip": "在航空公司预订国际机票，舱位等级分为：'Economy class'（经济舱）、'Premium economy'（超级经济舱）、'Business class'（商务舱）、'First class'（头等舱）。订票成功后航空公司会发放一个由6位字母数字组成的 'Confirmation code / PNR'（确认代码）。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hi! My name is John Lin. I'd like to book a flight to Rome, please.", "zh": "嗨！我叫林约翰。我想预订到罗马的班机。", "audio": "rumen_l22_01.mp3"}, {"speaker": "B", "en": "Do you wish to fly first class, business or economy?", "zh": "您想搭头等舱、商务舱还是经济舱？", "audio": "rumen_l22_02.mp3"}, {"speaker": "A", "en": "Economy.", "zh": "经济舱。", "audio": "rumen_l22_03.mp3"}, {"speaker": "B", "en": "Date of departure?", "zh": "出发的日期呢？", "audio": "rumen_l22_04.mp3"}, {"speaker": "A", "en": "July 4th.", "zh": "7月4日", "audio": "rumen_l22_05.mp3"}, {"speaker": "B", "en": "OK. You're booked on flight number CX167. It departs at 11:15 AM.", "zh": "好的。您预订的是CX167班机。早上11点15分起飞。", "audio": "rumen_l22_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Japan Airlines. Can I help you?", "zh": "日本航空公司。我可以为您效劳吗？", "audio": "rumen_l22_07.mp3"}, {"speaker": "B", "en": "Yes. I'm Peter Lai. I'd like to reserve a round-trip ticket to Paris, please.", "zh": "是的。我是赖彼得。麻烦你，我想预订到巴黎的来回机票。", "audio": "rumen_l22_08.mp3"}, {"speaker": "A", "en": "Which class? And for when?", "zh": "您要搭什么舱位？还有时间是什么时候？", "audio": "rumen_l22_09.mp3"}, {"speaker": "B", "en": "Business class; for this Sunday.", "zh": "商务舱；时间是这个星期天。", "audio": "rumen_l22_10.mp3"}, {"speaker": "A", "en": "One moment, please. OK. I've booked you on flight number 007. lt departs at 5 :30 PM. Please call back on Friday to reconfirm.", "zh": "请稍候。好了，我已为您订了下午5：30起飞的007号班机。请在星期五打电话来再确认。", "audio": "rumen_l22_11.mp3"}, {"speaker": "B", "en": "OK.", "zh": "好的。", "audio": "rumen_l22_12.mp3"}, {"speaker": "A", "en": "Your confirmation code number is XE3849.", "zh": "您的确认代码是XE3849。", "audio": "rumen_l22_13.mp3"}, {"speaker": "B", "en": "Thank you.", "zh": "谢谢。", "audio": "rumen_l22_14.mp3"}]}], "reading": null, "vocab": [{"word": "economy class", "phonetic": "[ɪˈkɑːnəmi klæs]", "pos": "n.", "meaning": "经济舱（客机基础舱位）", "modern_tip": "性价比最高的舱位，口语中有时也称作 'coach'（美式口语经常说 'fly coach'）。", "example": {"en": "Our company policy requires all staff to fly economy class on domestic trips.", "zh": "公司规定国内出差所有员工一律乘坐经济舱。"}}, {"word": "business class", "phonetic": "[ˈbɪznəs klæs]", "pos": "n.", "meaning": "商务舱", "modern_tip": "长途洲际飞行的豪华舒适舱位，提供平躺座椅和高级餐饮。", "example": {"en": "I used my frequent flyer miles to upgrade to business class.", "zh": "我用航空常旅客里程升级到了商务舱。"}}, {"word": "round-trip ticket", "phonetic": "[ˌraʊnd ˈtrɪp ˈtɪkɪt]", "pos": "n.", "meaning": "往返机票 / 双程票", "modern_tip": "美式英语称往返票为 'round-trip ticket'，英式英语习惯称作 'return ticket'；单程票为 'one-way ticket'。", "example": {"en": "A round-trip ticket to London is much cheaper than two one-way tickets.", "zh": "去伦敦的往返机票比买两张单程票划算得多。"}}, {"word": "confirmation code", "phonetic": "[ˌkɑːnfərˈmeɪʃn koʊd]", "pos": "n.", "meaning": "预订确认代码（如 XE3849）", "modern_tip": "去机场值机柜台或在自助值机机器上输入该代码，即可直接调出全套行程并打印登机牌。", "example": {"en": "Please keep your confirmation code handy when you arrive at the airport.", "zh": "到达机场时，请随手准备好您的预订确认代码。"}}], "grammar": [{"num": "01", "title": "【机票预订四大必备信息要素】", "formulas": ["目的地：I'd like to book a flight to [城市/国家], please.", "舱位：Do you wish to fly first class, business or economy?", "单双程：One-way or round-trip?", "出发与返程日：Date of departure / Date of return?"], "desc": ["订机票沟通中，掌握这四个维度的精准词汇，无论是电话订票还是在航司官网选票都能一眼看懂、一清二楚。"], "examples": ["I need a round-trip ticket to Paris departing on July 4th.", "Which class would you prefer to travel in?"]}, {"num": "02", "title": "【航班号与时刻读法】flight number & departs at", "formulas": ["航班号报法：flight number 007（读作 double-o seven 或 zero zero seven）", "起飞时刻：It departs at 11:15 AM (eleven fifteen a.m.)"], "desc": ["航司柜台确认订单时常说：'You're booked on flight number CX167. It departs at 11:15 AM.'（您预订的是CX167航班，上午11点15分起飞）。"], "examples": ["Flight UA888 departs from Gate 45 at 3:30 PM.", "Please call back on Friday to reconfirm your booking."]}], "connected_speech": ["弱读连音：'a flight to Rome' 连读为 /ə ˈflaɪt tə roʊm/，to 弱读为 /tə/。", "双元音节奏：'July 4th' 重音在 July 的后音节 /dʒuːˈlaɪ/，紧跟序数词 fourth /fɔːrθ/。", "代码字母清晰报读：'XE3849' 报字母与数字时字字清晰有力，中间留半拍微停顿。"], "substitution": [], "exercises": []}, {"num": 23, "title_en": "At the Airport I", "title_zh": "在机场（一）", "type": "dialogue", "category": "日常高频情境口语", "tip": "在国际机场值机（Check in），柜台地勤必问两个核心问题：'Smoking or non-smoking?'（吸烟区还是无烟区，如今全机禁烟已成历史）和 'Aisle or window seat?'（靠过道还是靠窗的座位？）。托运行李叫 'check in luggage'，随身行李叫 'carry-on luggage'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "This is the arrival lounge.", "zh": "这里是入境大厅。", "audio": "rumen_l23_01.mp3"}, {"speaker": "B", "en": "I know. Where is the departure lounge?", "zh": "我知道。出境大厅在哪里呢？", "audio": "rumen_l23_02.mp3"}, {"speaker": "A", "en": "Come. Follow me.", "zh": "来吧，跟我走。", "audio": "rumen_l23_03.mp3"}, {"speaker": "B", "en": "There! The check-in counters are over there.", "zh": "那里！办理登机手续的柜台在那里。", "audio": "rumen_l23_04.mp3"}, {"speaker": "A", "en": "Don't we have to go pay the airport tax first?", "zh": "我们不用先去付机场税吗？", "audio": "rumen_l23_05.mp3"}, {"speaker": "B", "en": "No. We pay it after we check in.", "zh": "不用。先办完登机手续后再付。", "audio": "rumen_l23_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Good morning. May I have your passport, please?", "zh": "早安。请把你的护照给我好吗？", "audio": "rumen_l23_07.mp3"}, {"speaker": "B", "en": "Here you are.", "zh": "在这儿。", "audio": "rumen_l23_08.mp3"}, {"speaker": "A", "en": "Smoking or non-smoking?", "zh": "你要坐在吸烟区或非吸烟区？", "audio": "rumen_l23_09.mp3"}, {"speaker": "B", "en": "Non-smoking.", "zh": "非吸烟区。", "audio": "rumen_l23_10.mp3"}, {"speaker": "A", "en": "Aisle or window seat?", "zh": "你要靠过道还是靠窗的座位？", "audio": "rumen_l23_11.mp3"}, {"speaker": "B", "en": "Window seat, please.", "zh": "请给我靠窗的座位。", "audio": "rumen_l23_12.mp3"}, {"speaker": "A", "en": "Do you have any luggage to check in?", "zh": "你有任何行李要托运吗？", "audio": "rumen_l23_13.mp3"}, {"speaker": "B", "en": "Yes. This is my carry-on luggage and I'll check in these two suitcases.", "zh": "有的。这是我的随身行李，这两个行李箱我要托运。", "audio": "rumen_l23_14.mp3"}]}], "reading": null, "vocab": [{"word": "aisle seat vs. window seat", "phonetic": "[aɪl siːt / ˈwɪndoʊ siːt]", "pos": "n.", "meaning": "靠走道座位 vs. 靠窗座位", "modern_tip": "【高频避坑】aisle 中的字母 s 不发音，读作 /aɪl/（发音跟 I'll 一模一样）；中间座位叫 middle seat。", "example": {"en": "Would you prefer an aisle seat or a window seat? -- An aisle seat, please.", "zh": "您倾向靠过道还是靠窗的座位？-- 靠过道的，谢谢。"}}, {"word": "carry-on luggage", "phonetic": "[ˈkæri ɑːn ˈlʌɡɪdʒ]", "pos": "n.", "meaning": "随身登机行李（不托运的登机箱/背包）", "modern_tip": "可以直接带上客舱放进头顶行李架的随身行李，在英式英语中也叫 hand luggage。", "example": {"en": "Is this backpack your only carry-on luggage? -- Yes, just this one.", "zh": "这个背包是您唯一的随身行李吗？-- 是的，就这一个。"}}, {"word": "arrival lounge vs. departure lounge", "phonetic": "[əˈraɪvl laʊndʒ / dɪˈpɑːrtʃər laʊndʒ]", "pos": "n.", "meaning": "到达大厅 / 入境大厅 vs. 出发大厅 / 候机大厅", "modern_tip": "机场航站楼两大核心区域：接机看 Arrivals，出发登机看 Departures。", "example": {"en": "My friends will meet me right outside the arrival lounge.", "zh": "我朋友们会在到达大厅外面正迎候我。"}}, {"word": "check-in counter", "phonetic": "[ˈtʃek ɪn ˈkaʊntər]", "pos": "n.", "meaning": "值机柜台 / 办登机手续的柜台", "modern_tip": "航司在机场大厅办理领登机牌、托运行李的专门排队服务柜台。", "example": {"en": "Where are the check-in counters for Delta Air Lines?", "zh": "达美航空的值机柜台在哪里？"}}], "grammar": [{"num": "01", "title": "【选座核心表达】Aisle vs. Window 座位博弈", "formulas": ["靠窗（看风景、睡觉不被打扰）：Window seat, please.", "靠走道（方便起身上洗手间、腿部伸展）：Aisle seat, please.", "前排安全出口大空间：Exit row seat, please."], "desc": ["长途洲际飞行（超过8小时）很多成年人更偏爱 aisle seat，因为出入走动无需惊动邻座；", "短途白昼飞行看云海日出则首选 window seat。"], "examples": ["Can I have a window seat near the front of the cabin?", "Do you have any aisle seats left in the economy section?"]}, {"num": "02", "title": "【行李两大阵营】check in luggage vs. carry-on", "formulas": ["托运行李：luggage to check in / checked baggage", "随身带上飞机：carry-on luggage / hand baggage", "表达搭配：This is my carry-on and I'll check in these two suitcases."], "desc": ["注意语法细节：luggage 和 baggage 是不可数名词，不能加复数 s；若要数件数，必须用 a piece of luggage 或 suitcases（箱子）。"], "examples": ["How many pieces of checked luggage are allowed per passenger?", "Please place your carry-on luggage into the overhead bin."]}], "connected_speech": ["静音字母攻坚：'aisle' 中的 s 绝对不发音，干净读出 /aɪl/，与 seat 连缀为 /ˈaɪl siːt/。", "动副连读：'check in these two suitcases' 连读为 /ˈtʃe-kɪn/。", "反问疑问句语调：'Don't we have to go pay the airport tax first?' 句尾带着疑惑明显扬起升调（↗）。"], "substitution": [], "exercises": []}, {"num": 24, "title_en": "At the Airport II", "title_zh": "在机场（二）", "type": "dialogue", "category": "日常高频情境口语", "tip": "在机场行李托运过秤时，超出免费额度的叫 'overweight'，需要缴纳 'excess baggage charge'（超重行李费）。办妥后领取的登机卡叫 'Boarding pass'，上面清楚印有登机口（Gate number）。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Please fill out these tags and attach them to your suitcases. Then put them on the scale.", "zh": "请填好这些标签后把它们系在你的行李箱上。然后把它们放在秤上。", "audio": "rumen_l24_01.mp3"}, {"speaker": "B", "en": "OK.", "zh": "好的。", "audio": "rumen_l24_02.mp3"}, {"speaker": "A", "en": "I'm afraid your luggage is overweight. You'll have to pay an excess baggage charge.", "zh": "恐怕你的行李超重了。你必须额外付行李超重费。", "audio": "rumen_l24_03.mp3"}, {"speaker": "B", "en": "How much will that be?", "zh": "那要多少钱？", "audio": "rumen_l24_04.mp3"}, {"speaker": "A", "en": "Let me see -- US $10.", "zh": "让我看看——10美元。", "audio": "rumen_l24_05.mp3"}, {"speaker": "B", "en": "That's not too bad.", "zh": "还不算太糟。", "audio": "rumen_l24_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Here are your tickets. The baggage claim stubs are attached to them.", "zh": "这里是你的机票。领取行李的存根就附在上面。", "audio": "rumen_l24_07.mp3"}, {"speaker": "B", "en": "Thank you.", "zh": "谢谢。", "audio": "rumen_l24_08.mp3"}, {"speaker": "A", "en": "And here is your boarding pass. You board at Gate 12.", "zh": "这儿是你的登机证。你在12号门登机。", "audio": "rumen_l24_09.mp3"}, {"speaker": "B", "en": "OK. Is that all?", "zh": "好的。就这样吗？", "audio": "rumen_l24_10.mp3"}, {"speaker": "A", "en": "No. Please wait here till your luggage goes through the X-ray machine.", "zh": "还没。请在这里等你的行李通过X光检测机。", "audio": "rumen_l24_11.mp3"}, {"speaker": "B", "en": "OK.", "zh": "好吧。", "audio": "rumen_l24_12.mp3"}, {"speaker": "A", "en": "Have a nice flight.", "zh": "祝你搭机愉快。", "audio": "rumen_l24_13.mp3"}, {"speaker": "B", "en": "Thank You.", "zh": "谢谢。", "audio": "rumen_l24_14.mp3"}]}], "reading": null, "vocab": [{"word": "boarding pass", "phonetic": "[ˈbɔːrdɪŋ pæs]", "pos": "n.", "meaning": "登机牌 / 登机证", "modern_tip": "通过机场安检、进入登机口登机必须出示的核心纸质或电子凭证，印有座位号和登机时间。", "example": {"en": "Keep your boarding pass and passport together until you board the plane.", "zh": "在登机之前，请把您的登机牌和护照放在一起随身保管。"}}, {"word": "overweight", "phonetic": "[ˌoʊvərˈweɪt]", "pos": "adj.", "meaning": "（行李）超重的 / 超出规定重量的", "modern_tip": "地勤称重后常说的提醒句：'I'm afraid your suitcase is slightly overweight'。", "example": {"en": "The limit is 23 kg, so your bag is 2 kg overweight.", "zh": "限重是23公斤，所以您的箱子超重了2公斤。"}}, {"word": "excess baggage charge", "phonetic": "[ɪkˈses ˈbæɡɪdʒ tʃɑːrdʒ]", "pos": "n.", "meaning": "超重行李附加费", "modern_tip": "行李超过规定重量或件数上限时，航司收取的额外罚款/手续费。", "example": {"en": "How much is the excess baggage charge per extra kilogram?", "zh": "每超重一公斤的行李附加费是多少？"}}, {"word": "X-ray machine", "phonetic": "[ˈeks reɪ məˈʃiːn]", "pos": "n.", "meaning": "X光安检检测机 / 透视扫描仪", "modern_tip": "所有托运行李和随身包物必须通过的透视安检设备。", "example": {"en": "Please place your laptops and liquids in the tray for the X-ray machine.", "zh": "请把您的笔记本电脑和液体放入托盘通过X光机检测。"}}], "grammar": [{"num": "01", "title": "【机场登机指示三部曲】", "formulas": ["第一步（行李标签）：Please fill out these tags and attach them to your suitcases.", "第二步（安检等待）：Please wait here till your luggage goes through the X-ray machine.", "第三步（登机口指引）：You board at Gate [号码]. Have a nice flight!"], "desc": ["在动词 board 后面直接跟登机口介词短语 'board at Gate 12'；", "地勤办妥手续告别时必说的暖心祝福语：'Have a nice flight!'（旅途愉快！）。"], "examples": ["Flight 205 is now boarding at Gate 18B.", "Have a safe trip and enjoy your flight!"]}, {"num": "02", "title": "【客套委婉否定法】I'm afraid...", "formulas": ["句型：I'm afraid + 从句（恐怕……/ 很遗憾……）", "应用：I'm afraid your luggage is overweight.", "应用：I'm afraid we have no seats left on this flight."], "desc": ["在服务业中，直接说 'Your bag is too heavy' 会显得生硬指责；加上前缀 'I'm afraid...'（恐怕……）能瞬间缓和语气，体现国际礼仪修养。"], "examples": ["I'm afraid the museum is closed on Mondays.", "I'm afraid we cannot accept personal checks here."]}], "connected_speech": ["连读同化：'attach them' 连读为 /əˈtætʃ-ðəm/，音变平滑。", "闪音技巧：'wait here till' 连缀，/t/ 音利落过渡。", "道别祝福语调：'Have a nice flight!' 语调轻快上扬，传递热情的旅行祝愿。"], "substitution": [], "exercises": []}, {"num": 25, "title_en": "At the Post Office", "title_zh": "在邮局", "type": "dialogue", "category": "日常高频情境口语", "tip": "在邮局（Post Office）寄东西，挂号信叫 'Register a letter'（能全程跟踪签收，重要证件必备）；寄往国外的平信或明信片选航空件叫 'Send by air mail'。信件封口叫 'seal the envelope'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "I'd like to register this letter, please.", "zh": "麻烦你，我想用挂号寄这封信。", "audio": "rumen_l25_01.mp3"}, {"speaker": "B", "en": "Where to?", "zh": "寄到哪里？", "audio": "rumen_l25_02.mp3"}, {"speaker": "A", "en": "Los Angeles.", "zh": "洛杉矶。", "audio": "rumen_l25_03.mp3"}, {"speaker": "B", "en": "Ok. Let me weigh it. That'll be three dollars, please.", "zh": "好的，让我来称一下重量。邮资是3美元，麻烦你。", "audio": "rumen_l25_04.mp3"}, {"speaker": "A", "en": "Here you are. Do I have to fill out a form?", "zh": "拿去吧。我必须填写表格吗？", "audio": "rumen_l25_05.mp3"}, {"speaker": "B", "en": "No. Just give me your name, address and telephone number.", "zh": "不必。只要把你的姓名、住址和电话给我就行了。", "audio": "rumen_l25_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "I'd like to send this by air mail, please.", "zh": "我想要用航空邮寄这个，麻烦你。", "audio": "rumen_l25_07.mp3"}, {"speaker": "B", "en": "Is it a birthday card?", "zh": "那是生日贺卡吗？", "audio": "rumen_l25_08.mp3"}, {"speaker": "A", "en": "Yes. Why do you ask?", "zh": "是的。你为什么这样问？", "audio": "rumen_l25_09.mp3"}, {"speaker": "B", "en": "Cards are cheaper than letters.", "zh": "卡片比信件要来得便宜。", "audio": "rumen_l25_10.mp3"}, {"speaker": "A", "en": "Oh! Really?", "zh": "哦！真的吗？", "audio": "rumen_l25_11.mp3"}, {"speaker": "B", "en": "You can't seal the envelope, though.", "zh": "不过你不能把信封封起来。", "audio": "rumen_l25_12.mp3"}, {"speaker": "A", "en": "Ok. How much for the stamps?", "zh": "好吧。我要贴多少钱的邮票？", "audio": "rumen_l25_13.mp3"}, {"speaker": "B", "en": "Two dollars.", "zh": "2美元。", "audio": "rumen_l25_14.mp3"}]}], "reading": null, "vocab": [{"word": "register a letter", "phonetic": "[ˈredʒɪstər ə ˈletər]", "pos": "phrase", "meaning": "挂号寄信（提供跟踪单号，需签收）", "modern_tip": "寄送护照、合同、支票等贵重文件的首选邮寄方式（Registered mail）。", "example": {"en": "I need to register this legal document so I have proof of delivery.", "zh": "我需要挂号寄出这份法律文件，以便保留送达证明。"}}, {"word": "air mail", "phonetic": "[er meɪl]", "pos": "n.", "meaning": "航空邮件 / 航空平信", "modern_tip": "跨国寄送明信片或普通信件的最常用方式，对应海运水运的 surface mail。", "example": {"en": "How long does air mail take from New York to Beijing? -- About a week.", "zh": "从纽约到北京航空邮件要寄多久？-- 大约一周左右。"}}, {"word": "seal the envelope", "phonetic": "[siːl ðiː ˈenvəloʊp]", "pos": "phrase", "meaning": "封上信封 / 密封信封", "modern_tip": "邮寄贺卡或特定印刷品享受优惠邮费时，邮局常规定不能封死信封，以便抽查。", "example": {"en": "Make sure you include the photos before you seal the envelope.", "zh": "在你把信封封死之前，一定要确认照片已经放进去了。"}}, {"word": "weigh it", "phonetic": "[weɪ ɪt]", "pos": "phrase", "meaning": "称一下它的重量", "modern_tip": "邮局柜员把包裹或信件放到电子秤上计算邮资的标准动作。", "example": {"en": "Put your parcel on the scale, please. Let me weigh it.", "zh": "请把包裹放在秤上，让我称一下重量。"}}], "grammar": [{"num": "01", "title": "【邮寄请求两大经典句型】I'd like to register... vs. I'd like to send... by...", "formulas": ["挂号邮寄：I'd like to register this letter to [目的地], please.", "按某种交通方式邮寄：I'd like to send this parcel by air mail / express mail."], "desc": ["在邮政窗口，柜员第一句永远是确认目的地：'Where to?'（寄到哪里？），称重后报出价格：'That'll be three dollars, please.'。"], "examples": ["I'd like to send this package to Canada by express delivery.", "How much would it cost to register this parcel?"]}, {"num": "02", "title": "【形容词比较级表价格优劣】cheaper than...", "formulas": ["结构：[事物A] are cheaper than [事物B]", "课文原句：Cards are cheaper than letters.（贺卡邮资比信件更便宜）"], "desc": ["副词 though 放在句尾时，相当于中文的‘不过/然而’，属于口语中极高频的轻巧转折词：'You can't seal the envelope, though.'（不过你不能把信封封死喔）。"], "examples": ["Surface mail is cheaper than air mail, but it takes much longer.", "It's a nice apartment. The rent is quite high, though."]}], "connected_speech": ["动代连读：'weigh it' 连读为 /ˈweɪ-jɪt/，双元音 /eɪ/ 顺畅滑入 /ɪt/。", "元音前冠词音变：'the envelope' 中的 the 读作 /ðiː/，因为 envelope 以元音开头。", "转折连读轻声：句尾 'though' 读作轻柔的 /ðoʊ/，音调下落，体现口语补充语气的自然从容。"], "substitution": [], "exercises": []}, {"num": 26, "title_en": "At the Doctor's", "title_zh": "看病", "type": "dialogue", "category": "日常高频情境口语", "tip": "在国外看医生描述病情，常见症状词块必须脱口而出：'have a fever'（发烧）、'have a sore throat'（嗓子疼）、'have the flu'（得了流感）、'need a shot'（需要打一针）。药剂师交待服药频次时最经典的表达是 'take these pills 3 times a day after meals'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Doctor, I think I have the flu.", "zh": "医生，我想我得了流行性感冒。", "audio": "rumen_l26_01.mp3"}, {"speaker": "B", "en": "Do you have a cough, too?", "zh": "你也有咳嗽吗？", "audio": "rumen_l26_02.mp3"}, {"speaker": "A", "en": "No. Not really.", "zh": "不，算不上真的咳嗽。", "audio": "rumen_l26_03.mp3"}, {"speaker": "B", "en": "Do you have a sore throat?", "zh": "喉咙会痛吗？", "audio": "rumen_l26_04.mp3"}, {"speaker": "A", "en": "A little. But I have a bit of a fever.", "zh": "一点点。但我有一点发烧。", "audio": "rumen_l26_05.mp3"}, {"speaker": "B", "en": "Ok. Let me have a look.", "zh": "好的。让我来看看。", "audio": "rumen_l26_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Open your mouth and say, &quot;Ah...!&quot;", "zh": "张开嘴巴说“啊...”！", "audio": "rumen_l26_07.mp3"}, {"speaker": "B", "en": "Ah...", "zh": "啊...", "audio": "rumen_l26_08.mp3"}, {"speaker": "A", "en": "Yes, it's quite serious. I think you need a shot.", "zh": "是了，情况相当严重。我想你得打一针。", "audio": "rumen_l26_09.mp3"}, {"speaker": "B", "en": "Is it going to hurt?", "zh": "会不会痛呢？", "audio": "rumen_l26_10.mp3"}, {"speaker": "A", "en": "Don't worry. It'll soon be over.", "zh": "别担心，很快就会结束的。", "audio": "rumen_l26_11.mp3"}, {"speaker": "B", "en": "Ouch!", "zh": "哎哟！", "audio": "rumen_l26_12.mp3"}, {"speaker": "A", "en": "OK. It's done. Also, take these pills 3 times a day after meals.", "zh": "好了，打完针了。还有，饭后服用这些药丸，一天三次。", "audio": "rumen_l26_13.mp3"}, {"speaker": "B", "en": "Ok. Thanks, doctor. Bye.", "zh": "好的。谢谢你，医生。再见。", "audio": "rumen_l26_14.mp3"}]}], "reading": null, "vocab": [{"word": "have the flu", "phonetic": "[hæv ðə fluː]", "pos": "phrase", "meaning": "得了流感（流行性感冒）", "modern_tip": "注意流感 flu 前面必须加定冠词 the（the flu）；普通感冒则用 a cold（如 'have a bad cold'）。", "example": {"en": "I'm shivering and aching all over. I think I have the flu.", "zh": "我在发抖而且全身酸痛，我想我得流感了。"}}, {"word": "sore throat", "phonetic": "[sɔːr θroʊt]", "pos": "n.", "meaning": "喉咙痛 / 咽喉发炎", "modern_tip": "形容身体部位酸痛发炎用 sore（如 sore eyes, sore muscles）。", "example": {"en": "Do you have any lozenges? I woke up with a terrible sore throat.", "zh": "你有润喉糖吗？我早晨醒来喉咙痛得要命。"}}, {"word": "need a shot", "phonetic": "[niːd ə ʃɑːt]", "pos": "phrase", "meaning": "需要打一针 / 打针", "modern_tip": "美语日常中把打针俗称作 'a shot'（如 flu shot 流感疫苗针），极少使用生硬的 injection。", "example": {"en": "The doctor said my infection is severe, so I need an antibiotic shot.", "zh": "医生说我感染挺严重的，所以我需要打一针抗生素。"}}, {"word": "take pills", "phonetic": "[teɪk pɪlz]", "pos": "phrase", "meaning": "吃药 / 服用药丸", "modern_tip": "英语中吃药永远用动词 take（take medicine / take pills），绝不能用 eat 或 drink！", "example": {"en": "Remember to take two pills every six hours with water.", "zh": "记得每六小时就水服用两粒药丸。"}}], "grammar": [{"num": "01", "title": "【生病症状三大黄金句型】have a fever & have a cold", "formulas": ["发烧：have a fever / have a bit of a fever（有一点发烧）", "咳嗽：have a cough / cough a lot", "咽喉痛：have a sore throat", "全身流感：have the flu"], "desc": ["向医生阐述病情时，'I have a bit of a fever'（我有一点点发烧）比单调的 'I am sick' 具体得多，便于医生快速开单验血化验。"], "examples": ["He has a mild fever and a runny nose.", "Drink plenty of fluids if you have a sore throat."]}, {"num": "02", "title": "【服药医嘱标准公式】take [药名] [次数] times a day [餐前/餐后]", "formulas": ["结构：Take these pills + [次数] + a day + after/before meals", "示例：Take these pills 3 times a day after meals.（饭后服药，一天三次）", "餐前空腹：take on an empty stomach"], "desc": ["在药瓶标签和药剂师口头交代中，这是全球通行频率最高的医嘱句式，务必听懂每一个时间节点。"], "examples": ["Take one capsule twice a day before breakfast and dinner.", "Is it going to hurt? -- Don't worry, it'll soon be over!"]}], "connected_speech": ["弱读连音：'bit of a fever' 连读为 /ˈbɪ-tə-və ˈfiː-vər/，of 弱化为 /əv/ 与 a 连读。", "牙齿齿音突破：'sore throat' 中的 throat 务必把舌尖轻咬齿间，发标准清齿擦音 /θ/。", "感叹词短音：'Ouch!' 爆发力强，音调迅速下挫，生动再现被打针扎到时的自然疼痛反应。"], "substitution": [], "exercises": []}, {"num": 27, "title_en": "At the Zoo", "title_zh": "在动物园", "type": "dialogue", "category": "日常高频情境口语", "tip": "在国外拍照时，让大家微笑的经典口令是喊 'Say cheese!'（因为发 /iː/ 音时嘴角自然向两边拉开如微笑）。形容动物体型巨大用 'gigantic'（比 big 震撼得多），野生濒危物种用 'endangered species'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Can I take a picture with the lion, Dad?", "zh": "我可以和狮子照张相吗，老爸？", "audio": "rumen_l27_01.mp3"}, {"speaker": "B", "en": "Sure. But don't go too near the cage.", "zh": "当然可以。不过不要太靠近笼子喔。", "audio": "rumen_l27_02.mp3"}, {"speaker": "A", "en": "I'll stand behind the railing.", "zh": "我会站在栏杆后面。", "audio": "rumen_l27_03.mp3"}, {"speaker": "B", "en": "OK. Are you ready? Say &quot;Cheese!&quot;", "zh": "好了，准备好了吗？说“Cheese”！", "audio": "rumen_l27_04.mp3"}, {"speaker": "A", "en": "Cheese!", "zh": "Cheese!", "audio": "rumen_l27_05.mp3"}, {"speaker": "B", "en": "That's a good one.", "zh": "这张照得很棒。", "audio": "rumen_l27_06.mp3"}, {"speaker": "A", "en": "Lions are beautiful, aren't they?", "zh": "狮子好漂亮喔，对不对？", "audio": "rumen_l27_07.mp3"}, {"speaker": "B", "en": "They sure are. After all, the lion is &quot;king of the beasts!&quot;", "zh": "当然啰。毕竟，狮子是“万兽之王”啊。", "audio": "rumen_l27_08.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Wow! Look at that elephant. It's gigantic!", "zh": "哇！看那头大象，好大喔！", "audio": "rumen_l27_09.mp3"}, {"speaker": "B", "en": "It sure is.", "zh": "它的确是。", "audio": "rumen_l27_10.mp3"}, {"speaker": "A", "en": "Can I feed it?", "zh": "我可以喂它吗？", "audio": "rumen_l27_11.mp3"}, {"speaker": "B", "en": "No. There's a no-feeding sign over there.", "zh": "不行。那儿有一个禁止喂食的标志。", "audio": "rumen_l27_12.mp3"}, {"speaker": "A", "en": "Poor elephant.", "zh": "可怜的大象。", "audio": "rumen_l27_13.mp3"}, {"speaker": "B", "en": "There aren't many elephants left in the world, are there?", "zh": "世界上所剩的大象不多了，不是吗？", "audio": "rumen_l27_14.mp3"}, {"speaker": "A", "en": "People kill them for their tusks. Now they are an endangered species.", "zh": "人们为取得象牙而杀害它们，现在它们成了濒临绝种动物。", "audio": "rumen_l27_15.mp3"}, {"speaker": "B", "en": "Man sometimes behaves worse than animals.", "zh": "人类的行为有时候连禽兽都不如。", "audio": "rumen_l27_16.mp3"}]}], "reading": null, "vocab": [{"word": "Say cheese!", "phonetic": "[seɪ tʃiːz]", "pos": "phrase", "meaning": "看镜头，笑一个！/ 说茄子！", "modern_tip": "全世界通用的拍照口令！摄影者喊 'Say cheese'，被拍者齐声喊 'Cheese!'，定格微笑瞬间。", "example": {"en": "Everyone gather around the birthday cake! One, two, three, say cheese!", "zh": "大家快围到生日蛋糕周围！一、二、三，笑一个！"}}, {"word": "gigantic", "phonetic": "[dʒaɪˈɡæntɪk]", "pos": "adj.", "meaning": "极其巨大的 / 庞大无比的", "modern_tip": "比 big 和 huge 强烈震撼得多，常用来形容大象、鲸鱼、摩天大楼等宏伟巨物。", "example": {"en": "Look at that blue whale model hanging from the ceiling, it's gigantic!", "zh": "看天花板上悬挂的那具蓝鲸模型，真是太庞大了！"}}, {"word": "endangered species", "phonetic": "[ɪnˈdeɪndʒərd ˈspiːʃiːz]", "pos": "n.", "meaning": "濒危物种 / 濒临绝灭的珍稀动物", "modern_tip": "现代生态环保与科普核心词，单数和复数同形，均为 species。", "example": {"en": "Giant pandas and African elephants are both protected endangered species.", "zh": "大熊猫和非洲象都是受到保护的珍稀濒危物种。"}}, {"word": "king of the beasts", "phonetic": "[kɪŋ əv ðə biːsts]", "pos": "phrase", "meaning": "万兽之王 / 百兽之王（指狮子）", "modern_tip": "西方文学和童话中对 lion（狮子）的传统霸气尊称。", "example": {"en": "With its magnificent golden mane, the lion is truly the king of the beasts.", "zh": "凭借威武雄壮的金色鬃毛，狮子当之无愧是万兽之王。"}}], "grammar": [{"num": "01", "title": "【反义疑问句确认事实】aren't they? & sure are", "formulas": ["陈述肯定 + 疑问否定：Lions are beautiful, aren't they?（狮子真漂亮，对不对？）", "笃定强烈赞同：They sure are!（确实如此！/ 可不是嘛！）"], "desc": ["副词 sure 在美式口语中经常用作强调副词（相当于 certainly/definitely），如 'It sure is!'（确实是！）或 'They sure are!'（可不是嘛！），语气热烈自然。"], "examples": ["That was a thrilling movie, wasn't it? -- It sure was!", "You sure look happy today! Did you get the promotion?"]}, {"num": "02", "title": "【拍照与合影三大实用句型】", "formulas": ["请求与某人/物合影：Can I take a picture with [人/物]?", "请路人帮忙拍一张：Could you take a picture of us, please?", "评价拍摄效果好：That's a good one!（这张拍得很棒！）"], "desc": ["在旅游景点请人拍照说 'Could you take a picture of us?'，拍完看相机屏幕称赞对方说 'That's a good one!'（这张拍得好），非常讨喜。"], "examples": ["Can we get a photo together before you leave?", "Just press this button here. Thanks, that's a fantastic shot!"]}], "connected_speech": ["弱读连音：'take a picture with' 连读为 /ˈteɪ-kə ˈpɪk-tʃər wɪð/，/k/ 音轻巧滑入 a。", "介词弱读：'king of the beasts' 中的 of 弱化为极轻的 /əv/。", "强调重音：'They sure are!' 重音强烈砸在 sure 和 are 上，体现由衷的叹服与赞美。"], "substitution": [], "exercises": []}, {"num": 28, "title_en": "Going to the Movies", "title_zh": "看电影", "type": "dialogue", "category": "日常高频情境口语", "tip": "在国外约看电影，问正在放映什么片子说 'What's playing tonight?'；买电影票选场次问 'What time is the next show?'。电影院小卖部（Concession stand）的标配是爆米花（Popcorn）和可乐（Coke）。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Can I have two tickets for Titanic, please?", "zh": "可以给我两张“铁达尼号”的票吗？", "audio": "rumen_l28_01.mp3"}, {"speaker": "B", "en": "For what time?", "zh": "什么时间的？", "audio": "rumen_l28_02.mp3"}, {"speaker": "A", "en": "The 9:30 p. m. show, please.", "zh": "麻烦晚上九点半那一场。", "audio": "rumen_l28_03.mp3"}, {"speaker": "B", "en": "I'm afraid it's full. How about the midnight show?", "zh": "恐怕已经客满了，午夜场如何？", "audio": "rumen_l28_04.mp3"}, {"speaker": "A", "en": "That'll be fine. Can I have our seats up front, please?", "zh": "可以，请给我前排的座位好吗？", "audio": "rumen_l28_05.mp3"}, {"speaker": "B", "en": "Sure. That'll be twenty dollars, please.", "zh": "没问题。麻烦你总共是20美元。", "audio": "rumen_l28_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Where were you last night?", "zh": "你昨晚到哪儿去了？", "audio": "rumen_l28_07.mp3"}, {"speaker": "B", "en": "I was at the movies. I went to see Titanic.", "zh": "我在看电影，我跑去看“铁达尼号”。", "audio": "rumen_l28_08.mp3"}, {"speaker": "A", "en": "How was it?", "zh": "好看吗？", "audio": "rumen_l28_09.mp3"}, {"speaker": "B", "en": "It was fantastic. The main actor and actress really did a good job.", "zh": "非常好看。男女主角演得真是棒极了。", "audio": "rumen_l28_10.mp3"}, {"speaker": "A", "en": "Sounds like it was a very good movie.", "zh": "听你这么说好像是部很棒的电影。", "audio": "rumen_l28_11.mp3"}, {"speaker": "B", "en": "You can say that again!", "zh": "你说的一点也没错！", "audio": "rumen_l28_12.mp3"}]}], "reading": null, "vocab": [{"word": "What's playing?", "phonetic": "[wɑːts ˈpleɪɪŋ]", "pos": "phrase", "meaning": "今天放映什么电影？/ 正在上映什么片子？", "modern_tip": "美语中询问影院当前档期上映排片最地道短语，不要说成 'What movie is showing'。", "example": {"en": "Let's check the cinema website to see what's playing this evening.", "zh": "我们上网查查电影院今晚都在放些什么片子吧。"}}, {"word": "concession stand", "phonetic": "[kənˈseʃn stænd]", "pos": "n.", "meaning": "影院小吃售卖部 / 零食水吧柜台", "modern_tip": "影院大厅售卖爆米花、汽水、热狗的小吃部专有名词。", "example": {"en": "I'll go grab some large buttered popcorn at the concession stand.", "zh": "我去小吃吧买一大份黄油爆米花。"}}, {"word": "showtime / show", "phonetic": "[ˈʃoʊtaɪm / ʃoʊ]", "pos": "n.", "meaning": "电影放映场次 / 放映时间", "modern_tip": "电影院的单场放映被称为 a show，放映时间叫 showtimes。", "example": {"en": "The 7:00 PM showtime is sold out, but there are seats for 9:15 PM.", "zh": "晚上7点的场次已经卖光了，不过9点15分还有座。"}}, {"word": "blockbuster", "phonetic": "[ˈblɑːkbʌstər]", "pos": "n.", "meaning": "票房大片 / 超级卖座大片", "modern_tip": "好莱坞商业大制作、风靡全球的高票房爆款电影专有美称。", "example": {"en": "Have you seen the latest sci-fi blockbuster in IMAX?", "zh": "你看过最近那部IMAX科幻商业大片了吗？"}}], "grammar": [{"num": "01", "title": "【相约看电影四大邀约步骤】", "formulas": ["第一步（邀约提议）：Do you feel like going to the movies tonight?", "第二步（挑选片目）：What kind of movies do you like? / What's playing?", "第三步（商定场次）：The next show starts at 8:00. Does that work for you?", "第四步（票务买单）：Two tickets for the 8 o'clock show, please."], "desc": ["在售票窗口购票时，直接报'张数 + 场次'（Two tickets for the 8 o'clock show, please），干净利落。"], "examples": ["Are there any good comedies playing right now?", "I'd like two adult tickets for Avatar in 3D, please."]}, {"num": "02", "title": "【座位优选表达】in the middle vs. in the back row", "formulas": ["中间黄金观影区：in the middle, about halfway back", "后排靠后：near the back row", "走道边进出方便：on the aisle"], "desc": ["选座时服务人员问 'Where would you like to sit?'，用这些方位词块能精准表达观影习惯。"], "examples": ["Could we get seats in the center, around row F or G?", "I prefer sitting near the back so I have a full view of the screen."]}], "connected_speech": ["连读同化：'What's playing' 连读为 /ˈwɑːts ˈpleɪ-ɪŋ/。", "介词弱化：'tickets for the show' 中的 for the 快速弱化为 /fər-ðə/。", "爆破连贯：'popcorn' 中的第一个 /p/ 强送气，第二个 /p/ 唇部迅速收紧不送气。"], "substitution": [], "exercises": []}, {"num": 29, "title_en": "Job Interviews", "title_zh": "求职面试", "type": "dialogue", "category": "日常高频情境口语", "tip": "在求职面试（Job Interview）中，阐述跳槽原因切忌抱怨前东家，而要表达为追求个人成长（'looking for better career development'）。询问薪酬福利时，加班叫 'work overtime'，年终奖叫 'year-end bonus'，带薪年假叫 'annual leave'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Tell me, Mr. Wang. Why do you want to join our company?", "zh": "告诉我，王先生。为何你想加入我们公司？", "audio": "rumen_l29_01.mp3"}, {"speaker": "B", "en": "It has a good reputation.", "zh": "贵公司有良好的声誉。", "audio": "rumen_l29_02.mp3"}, {"speaker": "A", "en": "Do you have any work experience?", "zh": "你有任何工作经验吗？", "audio": "rumen_l29_03.mp3"}, {"speaker": "B", "en": "Not much. But I am willing to learn.", "zh": "不太多。但我很愿意学习。", "audio": "rumen_l29_04.mp3"}, {"speaker": "A", "en": "Why did you quit your last job?", "zh": "你为什么辞去上一个工作？", "audio": "rumen_l29_05.mp3"}, {"speaker": "B", "en": "I think I'll have a better future with your company.", "zh": "我认为在贵公司我会比较有前途。", "audio": "rumen_l29_06.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Do you have any questions?", "zh": "你有任何问题吗？", "audio": "rumen_l29_07.mp3"}, {"speaker": "B", "en": "Yes. Will I have to work overtime?", "zh": "是的。我必须要加班吗？", "audio": "rumen_l29_08.mp3"}, {"speaker": "A", "en": "Sometimes.", "zh": "有时候要。", "audio": "rumen_l29_09.mp3"}, {"speaker": "B", "en": "How about holidays?", "zh": "那么放假呢？", "audio": "rumen_l29_10.mp3"}, {"speaker": "A", "en": "After a year, you'll get an annual leave of seven days.", "zh": "满一年后，你每年就会有7天的假期。", "audio": "rumen_l29_11.mp3"}, {"speaker": "B", "en": "And is there a year-end bonus?", "zh": "是否有年终奖金呢？", "audio": "rumen_l29_12.mp3"}, {"speaker": "A", "en": "That depends. If you work hard and the company makes money, you'll get one.", "zh": "那要视情况而定。如果你工作努力而且公司赚钱的话就会有。", "audio": "rumen_l29_13.mp3"}, {"speaker": "B", "en": "That sounds fair.", "zh": "听起来很合理。", "audio": "rumen_l29_14.mp3"}]}], "reading": null, "vocab": [{"word": "work overtime", "phonetic": "[wɜːrk ˈoʊvərtaɪm]", "pos": "phrase", "meaning": "加班 / 超时工作", "modern_tip": "职场核心动词短语，加班费叫 overtime pay。", "example": {"en": "Will I be expected to work overtime during the product launch?", "zh": "在产品发布期间我会被要求加班吗？"}}, {"word": "year-end bonus", "phonetic": "[ˌjɪr ˈend ˈboʊnəs]", "pos": "n.", "meaning": "年终奖金 / 年终花红", "modern_tip": "年终考核发放的绩效奖金，是谈薪资福利（Compensation package）时的必问项。", "example": {"en": "Our company offers a performance-based year-end bonus in January.", "zh": "我们公司在一月份发放基于绩效考核的年终奖。"}}, {"word": "annual leave", "phonetic": "[ˈænjuəl liːv]", "pos": "n.", "meaning": "带薪年假", "modern_tip": "工作满一年后员工享有的法定带薪假期（如 '10 days of annual leave'）。", "example": {"en": "Employees are entitled to 15 days of paid annual leave each year.", "zh": "员工每年享有15天的带薪年假。"}}, {"word": "reputation", "phonetic": "[ˌrepjuˈteɪʃn]", "pos": "n.", "meaning": "声誉 / 名望 / 口碑", "modern_tip": "面试回答'为什么想加入我们公司'的标准高情商金句：'Your company has an outstanding reputation in the industry'。", "example": {"en": "I applied here because of your company's great reputation for innovation.", "zh": "我申请贵公司是因为你们在创新领域享有极高的声誉。"}}], "grammar": [{"num": "01", "title": "【面试经典问答三大套路】经验、离职与公司选择", "formulas": ["问为何加入：Why do you want to join our company? -> It has a great reputation.", "问工作经验：Do you have any related experience? -> Not much, but I am very willing to learn.", "问离职原因：Why did you quit your last job? -> I'm looking for a better future and growth."], "desc": ["面试回答要展现积极正面、谦逊好学（willing to learn）的态度，给面试官留下充满潜力的好印象。"], "examples": ["I want to bring my design skills to your talented marketing team.", "Although I'm a fresh graduate, I learn fast and adapt quickly."]}, {"num": "02", "title": "【条件与权衡高频表达】That depends.", "formulas": ["视情况而定：That depends.（最经典口语回复）", "取决于某条件：It depends on company performance and individual goals."], "desc": ["当事情不能用简单 Yes 或 No 回答，需要看后续外部条件时，脱口而出 'That depends' 是极其成熟老练的回答方式。"], "examples": ["Are you free this weekend? -- That depends, what do you have in mind?", "That sounds fair and reasonable to me."]}], "connected_speech": ["弱读与连读：'willing to learn' 连读为 /ˈwɪ-lɪŋ tə lɜːrn/，to 弱化为 /tə/。", "复合词重音：'year-end bonus' 重音落在 end 和 bonus 首音节上。", "赞同句调：'That sounds fair' 语调坚定笃定，展现对合同条款的认可。"], "substitution": [], "exercises": []}, {"num": 30, "title_en": "Emergency Calls", "title_zh": "紧急电话", "type": "dialogue", "category": "日常高频情境口语", "tip": "在北美遇到紧急突发危难，报警求救电话统一拨打 911（读作 'nine-one-one'，绝不要读成 'nine-eleven'，因为 9-11 专指恐怖袭击事件）。报警时必须以最快速度报清三个关键：地点（Where）、出了什么事（What happened）、是否有人受伤。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "This is an emergency call! Get an ambulance here right away.", "zh": "这是紧急电话！请马上派一部救护车到这里来。", "audio": "rumen_l30_01.mp3"}, {"speaker": "B", "en": "Where are you calling from?", "zh": "你从哪里打的电话？", "audio": "rumen_l30_02.mp3"}, {"speaker": "A", "en": "I'm at No. 10 Zhong Hua Road.", "zh": "我在中华路10号。", "audio": "rumen_l30_03.mp3"}, {"speaker": "B", "en": "What's the problem?", "zh": "发生了什么事？", "audio": "rumen_l30_04.mp3"}, {"speaker": "A", "en": "A taxi ran into a truck.", "zh": "一辆出租车撞上了一部卡车。", "audio": "rumen_l30_05.mp3"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Fire! There's a fire. Come quick!", "zh": "失火了！发生火灾了，快点来！", "audio": "rumen_l30_06.mp3"}, {"speaker": "B", "en": "Where's the fire?", "zh": "哪里发生火灾了？", "audio": "rumen_l30_07.mp3"}, {"speaker": "A", "en": "At No. 7 Kaifeng Street.", "zh": "在开封街7号。", "audio": "rumen_l30_08.mp3"}, {"speaker": "B", "en": "What's burning?", "zh": "什么东西着火了？", "audio": "rumen_l30_09.mp3"}, {"speaker": "A", "en": "My restaurant is on fire.", "zh": "我的餐馆烧起来了。", "audio": "rumen_l30_10.mp3"}, {"speaker": "B", "en": "How did it happen?", "zh": "怎么发生的？", "audio": "rumen_l30_11.mp3"}, {"speaker": "A", "en": "A gas tank exploded.", "zh": "瓦斯桶爆炸。", "audio": "rumen_l30_12.mp3"}, {"speaker": "B", "en": "We'll be right there.", "zh": "我们马上到！", "audio": "rumen_l30_13.mp3"}]}], "reading": null, "vocab": [{"word": "Call 911!", "phonetic": "[kɔːl ˌnaɪn wʌn ˈwʌn]", "pos": "phrase", "meaning": "快打911报警！/ 呼叫紧急救援！", "modern_tip": "【读音严正警示】读作 'nine-one-one'，包含警察（Police）、救护车（Ambulance）、消防队（Fire department）三合一应急热线。", "example": {"en": "There's smoke coming from the apartment next door, call 911 immediately!", "zh": "隔壁公寓冒烟了，立刻打911！"}}, {"word": "ambulance", "phonetic": "[ˈæmbjələns]", "pos": "n.", "meaning": "救护车 / 急救车", "modern_tip": "有人重伤突发昏厥时请求救护车：'Please send an ambulance right away!'。", "example": {"en": "A pedestrian was hit by a car, we need an ambulance at Fifth and Main!", "zh": "有位行人被车撞了，我们在第五街和主街交叉口急需一辆救护车！"}}, {"word": "What's the emergency?", "phonetic": "[wɑːts ðiː ɪˈmɜːrdʒənsi]", "pos": "phrase", "meaning": "发生了什么紧急情况？", "modern_tip": "911接警调度员接通电话后的第一句标准开场白，以便立刻分类派警。", "example": {"en": "911, what's your emergency and what is the exact location?", "zh": "911报警台，请问发生什么紧急情况？您的具体地址在哪里？"}}, {"word": "stay on the line", "phonetic": "[steɪ ɑːn ðə laɪn]", "pos": "phrase", "meaning": "保持通话 / 别挂断电话", "modern_tip": "调度员在派车途中对报警人的安全提示：'Stay on the line with me until help arrives'。", "example": {"en": "Help is on the way. Stay calm and stay on the line with me.", "zh": "救援人员正在赶往现场。请保持镇静，不要挂断电话。"}}], "grammar": [{"num": "01", "title": "【911报警三要素黄金沟通闭环】", "formulas": ["第一步（自报事由）：There has been an accident / fire / robbery.", "第二步（精准地址）：I am at [具体地址/交叉路口].", "第三步（请求派遣）：Please send an ambulance and police right away!"], "desc": ["在紧急危难时刻，慌乱和英文不流畅是最大障碍。牢牢背诵：'Someone is hurt. Send an ambulance to [地点] right away!' 能在关键时刻拯救生命。"], "examples": ["My father collapsed and isn't breathing. Send an ambulance to 420 Elm Street!", "There's a break-in in progress at my neighbor's house."]}, {"num": "02", "title": "【求救救援状态通知】Help is on the way.", "formulas": ["调度员安抚：Help is on the way.（救援已经在路上了）", "赶赴现场：The paramedics / officers will be there in two minutes.", "安全指令：Don't move the injured person."], "desc": ["听到调度员说 'Help is on the way' 时，意味着警车或救护车已经鸣笛出动，此时继续听从调度员的电话急救指引（如心肺复苏 CPR）即可。"], "examples": ["Stay calm, ma'am. The fire trucks are already on the way.", "Please keep everyone away from the building."]}], "connected_speech": ["数字连读：'nine-one-one' 重音在最后一个 one 上，读作 /ˌnaɪn wʌn ˈwʌn/。", "辅音同化与失爆：'right away' 连读为 /ˈraɪ-tə-weɪ/，/t/ 闪音化为 /ɾ/。", "紧急语调：'Hurry, please!' 节奏紧凑急促，尾音落地充满紧迫感。"], "substitution": [], "exercises": []}];